rtant;}.tax_computation_company_currency{margin-bottom: 5px;}\n/* /hr_skills/static/src/scss/report_employee_cv.scss */\n div.o_employee_cv{font-family: 'Roboto', sans-serif; color: #16171a; font-size: 14px; padding: 0; margin: 0; position: relative;}div.o_employee_cv h1, div.o_employee_cv h2, div.o_employee_cv h3, div.o_employee_cv h4, div.o_employee_cv h5, div.o_employee_cv h6{font-weight: bolder;}div.o_employee_cv a{text-decoration: none;}div.o_employee_cv p{line-height: 1.5;}div.o_employee_cv:not(:last-child) .o_new_page{page-break-after: always;}div.o_employee_cv .o_sidebar{color: #fff; margin-top: -150px; margin-left: 500px; width: inherit; display: inline-block; max-width: 50%; min-width: 50%; box-sizing: border-box; vertical-align: top;}div.o_employee_cv .o_sidebar a{color: #fff;}div.o_employee_cv .o_sidebar .o_profile{padding: 30px; padding-top: 15px; background: rgba(0, 0, 0, 0.2); text-align: center; color: #fff;}div.o_employee_cv .o_sidebar .o_profile_name{font-size: 32px; font-weight: bolder; margin-bottom: 10px;}div.o_employee_cv .o_sidebar .o_profile_job{color: rgba(255, 255, 255, 0.9); font-size: 20px; font-weight: bold; margin-top: 0;}div.o_employee_cv .o_sidebar .o_profile_image{margin-bottom: 15px; width: 100px; float: right;}div.o_employee_cv .o_sidebar .o_social{list-style-type: none;}div.o_employee_cv .o_sidebar .o_social li{margin-bottom: 15px;}div.o_employee_cv .o_sidebar .o_social li:last-child{margin-bottom: 0;}div.o_employee_cv .o_sidebar .o_sidebar_section{padding: 15px;}div.o_employee_cv .o_sidebar .o_sidebar_title{text-transform: uppercase; font-size: 16px; font-weight: bold; margin-top: 0; margin-bottom: 15px;}div.o_employee_cv .o_sidebar .o_sidebar_education .o_sidebar_education_degree{font-size: 14px; margin-top: 0; margin-bottom: 0;}div.o_employee_cv .o_sidebar .o_sidebar_education .o_sidebar_education_line{margin-bottom: 15px; overflow-wrap: break-word;}div.o_employee_cv .o_sidebar .o_sidebar_education .o_sidebar_education_line:las