110	16	\N	1	1	Export Translations	base.language.export	\N	form	base/wizard/base_export_language_views.xml	primary	{"en_US": "<form string=\\"Export Translations\\">\\n                    <field name=\\"name\\" invisible=\\"1\\"/> <!-- The name is needed in the BinaryField component used to download the file -->\\n                    <group invisible=\\"state != 'choose'\\" string=\\"Export Settings\\">\\n                        <field name=\\"lang\\"/>\\n                        <field name=\\"format\\"/>\\n                        <field name=\\"export_type\\"/>\\n                        <field name=\\"modules\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\" invisible=\\"export_type == 'model'\\"/>\\n                        <field name=\\"model_id\\" options=\\"{'no_create': True}\\" invisible=\\"export_type == 'module'\\" required=\\"export_type == 'model'\\"/>\\n                        <field name=\\"model_name\\" invisible=\\"1\\"/> <!-- The model_name is needed for the option of the domain -->\\n                        <field name=\\"domain\\" widget=\\"domain\\" options=\\"{'model': 'model_name'}\\" invisible=\\"export_type == 'module'\\"/>\\n                    </group>\\n                    <div invisible=\\"state != 'get'\\">\\n                        <h2>Export Complete</h2>\\n                        <div invisible=\\"data\\">\\n                            <div class=\\"mb-2 rounded-2 overflow-hidden d-grid gap-2\\">\\n                                <div class=\\"alert alert-warning m-0 p-1 ps-3\\" role=\\"alert\\">\\n                                    <div name=\\"error\\" style=\\"white-space: pre-wrap;\\" invisible=\\"export_type == 'module'\\">\\n                                        Model\\n                                        <field name=\\"model_id\\" readonly=\\"1\\"/>\\n                                        does not contain translatable terms.<br/>\\n                                    </div>\\n                                    <div name=\\"error\\" style=\\"white-space: pre-wrap;\\" invisible=\\"export_type == 'model'\\">\\n                                        Modules\\n                                        <field name=\\"modules\\" widget=\\"many2many_tags\\" readonly=\\"1\\"/>\\n                                        do not contain translatable terms.<br/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            No file could be exported.\\n                        </div>\\n                        <div invisible=\\"not data\\">\\n                            <p>Here is the exported translation file: <field name=\\"data\\" readonly=\\"1\\" filename=\\"name\\"/></p>\\n                            <p>This file was generated using the universal <strong>Unicode/UTF-8</strong> file encoding, please be sure to view and edit\\n                               using the same encoding.</p>\\n                            <p>The next step depends on the file format:\\n                                <ul>\\n                                <li>CSV format: you may edit it directly with your favorite spreadsheet software,\\n                                    the rightmost column (value) contains the translations</li>\\n                                <li>PO(T) format: you should edit it with a PO editor such as\\n                                    <a href=\\"http://www.poedit.net/\\" target=\\"_blank\\">POEdit</a>, or your preferred text editor</li>\\n                                <li>TGZ format: bundles multiple PO(T) files as a single archive</li>\\n                                </ul>\\n                            </p>\\n                            <p>For more details about translating Odoo in your language, please refer to the\\n                                <a href=\\"https://github.com/odoo/odoo/wiki/Translations\\" target=\\"_blank\\">documentation</a>.</p>\\n                        </div>\\n                    </div>\\n                    <footer invisible=\\"state != 'choose'\\">\\n                        <button name=\\"act_getfile\\" data-hotkey=\\"q\\" string=\\"Export\\" type=\\"object\\" class=\\"btn-primary\\"/>\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\" string=\\"Cancel\\" type=\\"object\\" class=\\"btn-secondary\\"/>\\n                    </footer>\\n                    <footer invisible=\\"state != 'get'\\">\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\" string=\\"Close\\" type=\\"object\\" class=\\"btn-primary\\"/>\\n                    </footer>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Export Translations">\n                    <field name="name" invisible="1"/> <!-- The name is needed in the BinaryField component used to download the file -->\n                    <group invisible="state != 'choose'" string="Export Settings">\n                        <field name="lang"/>\n                        <field name="format"/>\n                        <field name="export_type"/>\n                        <field name="modules" widget="many2many_tags" options="{'no_create': True}" invisible="export_type == 'model'"/>\n                        <field name="model_id" options="{'no_create': True}" invisible="export_type == 'module'" required="export_type == 'model'"/>\n                        <field name="model_name" invisible="1"/> <!-- The model_name is needed for the option of the domain -->\n                        <field name="domain" widget="domain" options="{'model': 'model_name'}" invisible="export_type == 'module'"/>\n                    </group>\n                    <div invisible="state != 'get'">\n                        <h2>Export Complete</h2>\n                        <div invisible="data">\n                            <div class="mb-2 rounded-2 overflow-hidden d-grid gap-2">\n                                <div class="alert alert-warning m-0 p-1 ps-3" role="alert">\n                                    <div name="error" style="white-space: pre-wrap;" invisible="export_type == 'module'">\n                                        Model\n                                        <field name="model_id" readonly="1"/>\n                                        does not contain translatable terms.<br/>\n                                    </div>\n                                    <div name="error" style="white-space: pre-wrap;" invisible="export_type == 'model'">\n                                        Modules\n                                        <field name="modules" widget="many2many_tags" readonly="1"/>\n                                        do not contain translatable terms.<br/>\n                                    </div>\n                                </div>\n                            </div>\n                            No file could be exported.\n                        </div>\n                        <div invisible="not data">\n                            <p>Here is the exported translation file: <field name="data" readonly="1" filename="name"/></p>\n                            <p>This file was generated using the universal <strong>Unicode/UTF-8</strong> file encoding, please be sure to view and edit\n                               using the same encoding.</p>\n                            <p>The next step depends on the file format:\n                                <ul>\n                                <li>CSV format: you may edit it directly with your favorite spreadsheet software,\n                                    the rightmost column (value) contains the translations</li>\n                                <li>PO(T) format: you should edit it with a PO editor such as\n                                    <a href="http://www.poedit.net/" target="_blank">POEdit</a>, or your preferred text editor</li>\n                                <li>TGZ format: bundles multiple PO(T) files as a single archive</li>\n                                </ul>\n                            </p>\n                            <p>For more details about translating Odoo in your language, please refer to the\n                                <a href="https://github.com/odoo/odoo/wiki/Translations" target="_blank">documentation</a>.</p>\n                        </div>\n                    </div>\n                    <footer invisible="state != 'choose'">\n                        <button name="act_getfile" data-hotkey="q" string="Export" type="object" class="btn-primary"/>\n                        <button special="cancel" data-hotkey="x" string="Cancel" type="object" class="btn-secondary"/>\n                    </footer>\n                    <footer invisible="state != 'get'">\n                        <button special="cancel" data-hotkey="x" string="Close" type="object" class="btn-primary"/>\n                    </footer>\n                </form>\n            	f	t	2026-05-21 05:52:26.761124	2026-05-21 05:52:26.761124	\N
