stom_colors\\">\\n                                    <i class=\\"fa fa-repeat\\"/> Reset\\n                                    <field name=\\"custom_colors\\" class=\\"position-absolute top-0 start-0 w-100 h-100 opacity-0\\" nolabel=\\"1\\"/>\\n                                </a>\\n                            </div>\\n\\n                            <field name=\\"company_details\\" string=\\"Address\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"report_header\\" string=\\"Tagline\\" placeholder=\\"e.g. Global Business Solutions\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"report_footer\\" placeholder=\\"Write your phone, email, bank account, tax ID, ...\\" string=\\"Footer\\" options=\\"{'resizable': false}\\"/>\\n                            <field name=\\"paperformat_id\\" widget=\\"selection\\" required=\\"1\\"/>\\n                        </group>\\n                        <div class=\\"o_preview\\">\\n                            <field name=\\"preview\\" widget=\\"iframe_wrapper\\" class=\\"preview_document_layout d-flex justify-content-center mb-0\\"/>\\n                        </div>\\n                    </group>\\n                    <footer>\\n                        <button string=\\"Continue\\" class=\\"btn-primary\\" type=\\"object\\" name=\\"document_layout_save\\" data-hotkey=\\"q\\"/>\\n                        <button special=\\"cancel\\" data-hotkey=\\"x\\" string=\\"Discard\\"/>\\n                    </footer>\\n                </form>"}	<?xml version="1.0"?>\n<form class="o_document_layout">\n                    <group>\n                        <group class="o_document_layout_company">\n                            <field name="company_id" invisible="1"/>\n                            <field name="external_report_layout_id" invisible="1"/>\n                            <field name="logo_primary_color" invisible="1"/>\n                            <field name="logo_secondary_color" invisible="1"/>\n\n                            <field name="report_layout_id" string="Layout" widget="selection_badge" required="1" options="{'horizontal': true, 'size': 'sm'}"/>\n                            <field name="layout_background" string="Background" widget="selection" required="1"/>\n                            <field name="layout_background_image" options="{'accepted_file_extensions': 'image/*'}" invisible="layout_background != 'Custom'" required="layout_background == 'Custom'">Upload your file</field>\n                            <field name="font" string="Text" widget="selection" required="1"/>\n                            <field name="logo" string="Logo" widget="image" options="{'size': [0, 50]}"/>\n\n                            <label for="primary_color" string="Colors"/>\n                            <div class="o_document_layout_colors d-flex align-items-end mb-4">\n                                <field name="primary_color" widget="color" class="w-auto m-0 me-1"/>\n                                <field name="secondary_color" widget="color" class="w-auto m-0"/>\n                                <a class="o_custom_colors btn btn-secondary btn-sm position-relative ms-2" role="button" title="Reset to logo colors" invisible="not custom_colors">\n                                    <i class="fa fa-repeat"/> Reset\n                                    <field name="custom_colors" class="position-absolute top-0 start-0 w-100 h-100 opacity-0" nolabel="1"/>\n                                </a>\n                            </div>\n\n                            <field name="company_details" string="Address" options="{'resizable': false}"/>\n                            <field name="report_header" string="Tagline" placeholder="e.g. Global Business Solutions" options="{'resizable': false}"/>\n                            <field name="report_footer" placeholder="Write your phone, email, bank account, tax ID, ..." string="Footer" options="{'resizable': false}"/>\n                            <field name="paperformat_id" widget="selection" required="1"/>\n                        </group>\n                        <div class="o_preview">\n                            <field name="preview" widget="iframe_wrapper" class="preview_document_layout d-flex justify-content-center mb-0"/>\n                        </div>\n                    </group>\n                    <footer>\n                        <button string="Continue" class="btn-primary" type="object" name="document_layout_save" data-hotkey="q"/>\n                        <button special="cancel" data-hotkey="x" string="Discard"/>\n                    </footer>\n                </form>\n            	f	t	2026-05-21 05:52:48.487522	2026-05-21 05:52:48.487522	\N
220	16	\N	1	1	view_speedscope_index	\N	web.view_speedscope_index	qweb	web/views/speedscope_template.xml	primary	{"en_US": "<t t-name=\\"web.view_speedscope_index\\">\\n        &lt;!DOCTYPE html&gt;\\n        <html lang=\\"en\\">\\n            <head>\\n                <meta charset=\\"UTF-8\\"/>\\n                <title>Speedscope for odoo</title>\\n                <script>window.location.hash=\\"#localProfilePath=1\\"</script>\\n                <link href=\\"https://fonts.googleapis.com/css?family=Source+Code+Pro\\" rel=\\"stylesheet\\"/>\\n                <link rel=\\"stylesheet\\" t-attf-href=\\"{{cdn}}reset.8c46b7a1.css\\" crossorigin=\\"anonymous\\" integrity=\\"sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8=\\"/>\\n            </head>\\n            <body>\\n                <script t-attf-src=\\"{{cdn}}speedscope.026f36b0.js\\" crossorigin=\\"anonymous\\" integrity=\\"sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw=\\"/>\\n                <script>\\n                const b64 = '<t t-esc=\\"speedscope_base64\\"/>';\\n                document.addEventListener(\\"DOMContentLoaded\\", () =&gt; {\\n                    speedscope.loadFileFromBase64('Profile', b64);\\n                });\\n                </script>\\n            </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.view_speedscope_index">\n        &lt;!DOCTYPE html&gt;\n        <html lang="en">\n            <head>\n                <meta charset="UTF-8"/>\n                <title>Speedscope for odoo</title>\n                <script>window.location.hash="#localProfilePath=1"</script>\n                <link href="https://fonts.googleapis.com/css?family=Source+Code+Pro" rel="stylesheet"/>\n                <link rel="stylesheet" t-attf-href="{{cdn}}reset.8c46b7a1.css" crossorigin="anonymous" integrity="sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8="/>\n            </head>\n            <body>\n                <script t-attf-src="{{cdn}}speedscope.026f36b0.js" crossorigin="anonymous" integrity="sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw="/>\n                <script>\n                const b64 = '<t t-esc="speedscope_base64"/>';\n                document.addEventListener("DOMContentLoaded", () =&gt; {\n                    speedscope.loadFileFromBase64('Profile', b64);\n                });\n                </script>\n            </body>\n        </html>\n    </t>\n	f	t	2026-05-21 05:52:48.487522	2026-05-21 05:52:48.487522	\N
221	16	\N	1	1	view_memory	\N	web.view_memory	qweb	web/views/memory_template.xml	primary	{"en_US": "<t t-name=\\"web.view_memory\\">\\n        &lt;!DOCTYPE html&gt;\\n        <html lang=\\"en\\">\\n        <head>\\n            <meta charset=\\"UTF-8\\"/>\\n            <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\"/>\\n            <title>Memory Usage Visualization</title>\\n            <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"/>\\n            <script src=\\"https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels\\"/>\\n            <style>\\n                /* General body and layout styles */\\n                body {\\n                    font-family: Arial, sans-serif;\\n                    margin: 20px;\\n                    background-color: #f9f9f9;\\n                }\\n                .container {\\n                    display: flex;\\n                    flex-direction: column;\\n                    gap: 20px;\\n                }\\n\\n                /* Row definitions for the new layout */\\n                .top-row {\\n                    height: 40vh; /* Line graph takes 40% of the viewport height */\\n                }\\n                .bottom-row {\\n                    display: flex;\\n                    gap: 20px;\\n                    /* The height of this row will be determined by its content */\\n                }\\n\\n                /* Chart container styles */\\n                .chart-container {\\n                    position: relative;\\n                    background: #fff;\\n                    border: 1px solid #ddd;\\n                    border-radius: 5px;\\n                    padding: 15px;\\n                    height: 100%;\\n                    width: 100%;\\n                }\\n                \\n                /* Specific styling for the bottom row elements */\\n                .bar-chart-wrapper {\\n                    flex: 2; /* Bar chart takes 2/3 of the width */\\n                    min-height: 400px; /* Minimum height for the bar chart */\\n                }\\n                .traceback-panel {\\n                    flex: 1; /* Traceback panel takes 1/3 of the width */\\n                    background: #f5f5f5;\\n                    border: 1px solid #ddd;\\n                    border-radius: 5px;\\n                    padding: 15px;\\n                    overflow-y: auto;\\n                    min-height: 400px; /* Match min-height for alignment */\\n                    height: fit-content; /* Adjust height to content */\\n                }\\n\\n                /* Traceback panel content styling */\\n                .traceback-header {\\n                    font-weight: bold;\\n                    margin-bottom: 10px;\\n                    color: #333;\\n                }\\n                .traceback-item {\\n                    background: white;\\n                    margin: 5px 0;\\n                    padding: 8px;\\n                    border-radius: 3px;\\n                    border-left: 3px solid #007acc;\\n                    font-family: monospace;\\n                    font-size: 12px;\\n                }\\n                .traceback-file {\\n                    color: #007acc;\\n                    font-weight: bold;\\n                }\\n                .copyable {\\n                    cursor: pointer;\\n                    user-select: all;\\n                    padding: 2px 4px;\\n                    border-radius: 3px;\\n                    transition: background-color 0.2s;\\n                }\\n                .copyable:hover {\\n                    background-color: #e8f4f8;\\n                }\\n                .traceback-line {\\n                    color: #666;\\n                }\\n                .no-selection {\\n                    color: #999;\\n                    font-style: italic;\\n                    text-align: center;\\n                    padding-top: 50px;\\n                }\\n            </style>\\n        </head>\\n        <body>\\n            <div class=\\"container\\">\\n                <!-- Top row for the full-width line chart -->\\n                <div class=\\"top-row\\">\\n                    <div class=\\"chart-container\\">\\n                        <canvas id=\\"totalMemoryChart\\"/>\\n                    </div>\\n                </div>\\n                <!-- Bottom row for the bar chart and traceback panel -->\\n                <div class=\\"bottom-row\\">\\n                    <div class=\\"bar-chart-wrapper chart-container\\" id=\\"memoryChartContainer\\">\\n                        <canvas id=\\"memoryChart\\"/>\\n                    </div>\\n                    <div class=\\"traceback-panel\\" id=\\"tracebackPanel\\">\\n                        <div class=\\"no-selection\\">Click a point on the top chart, then a bar below to see details.</div>\\n                    </div>\\n                </div>\\n            </div>\\n\\n            <script>\\n                // Get data from Odoo template\\n                const rawData = JSON.parse(atob('<t t-esc=\\"memory_graph\\"/>'));\\n\\n                // --- UTILITY FUNCTIONS ---\\n                function formatBytes(bytes) {\\n                    if (bytes === 0) return '0 B';\\n                    const k = 1024;\\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\\n                    const value = bytes / Math.pow(k, i);\\n                    return `${value.toFixed(1)} ${sizes[i]}`;\\n                }\\n\\n                function formatTimestamp(timestamp) {\\n                    const date = new Date(timestamp * 1000);\\n                    return date.toLocaleString();\\n                }\\n\\n                function getLastFileFromTraceback(traceback) {\\n                    if (!traceback || traceback.length === 0) return \\"unknown:0\\";\\n                    const lastFrame = traceback[traceback.length - 1];\\n                    return `${lastFrame[0]}:${lastFrame[1]}`;\\n                }\\n                \\n                function getFullTracebackKey(traceback) {\\n                    if (!traceback || traceback.length === 0) return \\"unknown\\";\\n                    return traceback.map(frame =&gt; `${frame[0]}:${frame[1]}`).join(' -&gt; ');\\n                }\\n\\n                // --- DYNAMIC UI UPDATES ---\\n                function updateChartHeight(chart, dataLength) {\\n                    const container = document.getElementById('memoryChartContainer');\\n                    if (dataLength === 0) {\\n                        container.style.height = '400px'; // Reset to min-height\\n                        chart.resize();\\n                        return;\\n                    }\\n                    \\n                    const minBarHeight = 35; // Minimum height per bar for readability\\n                    const padding = 100; // Extra space for axes and labels\\n                    const newHeight = Math.max(400, (dataLength * minBarHeight) + padding);\\n                    \\n                    container.style.height = newHeight + 'px';\\n                    chart.resize();\\n                }\\n\\n                function showTraceback(traceback, size, fullTracebackKey) {\\n                    const panel = document.getElementById('tracebackPanel');\\n                    if (!traceback || traceback.length === 0) {\\n                        panel.innerHTML = '<div class=\\"no-selection\\">No traceback available</div>';\\n                        return;\\n                    }\\n\\n                    let html = `<div class=\\"traceback-header\\">Traceback (${formatBytes(size)})</div>`;\\n\\n                    if (fullTracebackKey) {\\n                        html += `\\n                            <div style=\\"margin-bottom: 10px; padding: 8px; background: #e8f4f8; border-radius: 3px; font-size: 11px; color: #555;\\">\\n                                <strong>Full Path:</strong> <span class=\\"copyable\\" title=\\"Click to select for copying\\">${fullTracebackKey}</span>\\n                            </div>\\n                        `;\\n                    }\\n\\n                    traceback.forEach(frame =&gt; {\\n                        const [filename, lineNo, functionName, code] = frame;\\n                        html += `\\n                            <div class=\\"traceback-item\\">\\n                                <div class=\\"traceback-file copyable\\" title=\\"Click to select for copying\\">${filename}:${lineNo}</div>\\n                                <div>in <strong>${functionName || 'unknown'}</strong></div>\\n                                ${code ? `<div class=\\"traceback-line\\">${code}</div>` : ''}\\n                            </div>\\n                        `;\\n                    });\\n\\n                    panel.innerHTML = html;\\n                }\\n\\n                // --- CHART LOGIC ---\\n                const totalSizes = rawData.map(entry =&gt;\\n                    entry.samples.reduce((sum, sample) =&gt; sum + sample.size, 0)\\n                );\\n                const lineLabels = rawData.map(entry =&gt; formatTimestamp(entry.start));\\n\\n                let selectedIndexes = [];\\n                let currentBreakdownData = [];\\n\\n                const updateBarChart = () =&gt; {\\n                    if (selectedIndexes.length === 1) {\\n                        const entry = rawData[selectedIndexes[0]];\\n                        const groupedData = {};\\n                        entry.samples.forEach(sample =&gt; {\\n                            const key = getLastFileFromTraceback(sample.traceback);\\n                            if (!groupedData[key]) {\\n                                groupedData[key] = { size: 0, traceback: sample.traceback, samples: [] };\\n                            }\\n                            groupedData[key].size += sample.size;\\n                            groupedData[key].samples.push(sample);\\n                        });\\n\\n                        currentBreakdownData = Object.entries(groupedData).map(([key, data]) =&gt; ({\\n                            label: key,\\n                            size: data.size,\\n                            traceback: data.traceback,\\n                            samples: data.samples\\n                        })).sort((a, b) =&gt; b.size - a.size);\\n\\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\\n                        breakdownChart.data.datasets = [{\\n                            label: `Memory Usage`,\\n                            data: currentBreakdownData.map(item =&gt; item.size),\\n                            backgroundColor: 'rgba(54, 162, 235, 0.6)',\\n                            borderColor: 'rgba(54, 162, 235, 1)',\\n                            borderWidth: 1\\n                        }];\\n                        breakdownChart.options.plugins.title.text = `Memory Breakdown for ${formatTimestamp(entry.start)}`;\\n\\n                    } else if (selectedIndexes.length === 2) {\\n                        const [idx1, idx2] = selectedIndexes.sort((a, b) =&gt; a - b);\\n                        const entry1 = rawData[idx1];\\n                        const entry2 = rawData[idx2];\\n\\n                        const groupDataByFullTraceback = (entry) =&gt; {\\n                            const grouped = {};\\n                            entry.samples.forEach(sample =&gt; {\\n                                const key = getFullTracebackKey(sample.traceback);\\n                                if (!grouped[key]) {\\n                                    grouped[key] = { size: 0, traceback: sample.traceback, lastFile: getLastFileFromTraceback(sample.traceback) };\\n                                }\\n                                grouped[key].size += sample.size;\\n                            });\\n                            return grouped;\\n                        };\\n\\n                        const data1 = groupDataByFullTraceback(entry1);\\n                        const data2 = groupDataByFullTraceback(entry2);\\n                        const labelSet = new Set([...Object.keys(data1), ...Object.keys(data2)]);\\n                        \\n                        let diffData = [];\\n                        labelSet.forEach(fullTracebackKey =&gt; {\\n                            const size1 = data1[fullTracebackKey]?.size || 0;\\n                            const size2 = data2[fullTracebackKey]?.size || 0;\\n                            const diff = size2 - size1;\\n                            if (diff !== 0) {\\n                                const item = data2[fullTracebackKey] || data1[fullTracebackKey];\\n                                diffData.push({ \\n                                    label: item.lastFile,\\n                                    diff: diff,\\n                                    traceback: item.traceback,\\n                                    fullTracebackKey: fullTracebackKey\\n                                });\\n                            }\\n                        });\\n\\n                        currentBreakdownData = diffData.sort((a, b) =&gt; b.diff - a.diff);\\n\\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\\n                        breakdownChart.data.datasets = [{\\n                            label: `Difference`,\\n                            data: currentBreakdownData.map(item =&gt; item.diff),\\n                            backgroundColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 0.6)' : 'rgba(255, 99, 132, 0.6)',\\n                            borderColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 1)' : 'rgba(255, 99, 132, 1)',\\n                            borderWidth: 1\\n                        }];\\n                        breakdownChart.options.plugins.title.text = `Memory Difference: ${formatTimestamp(entry2.start)} vs ${formatTimestamp(entry1.start)}`;\\n\\n                    } else {\\n                        currentBreakdownData = [];\\n                        breakdownChart.data.labels = [];\\n                        breakdownChart.data.datasets = [];\\n                        breakdownChart.options.plugins.title.text = 'Memory Breakdown';\\n                        document.getElementById('tracebackPanel').innerHTML = \\n                            '<div class=\\"no-selection\\">Click a point on the top chart, then a bar below to see details.</div>';\\n                    }\\n                    \\n                    updateChartHeight(breakdownChart, currentBreakdownData.length);\\n                    breakdownChart.update();\\n                    totalChart.update();\\n                };\\n\\n                // --- CHART INSTANTIATION ---\\n                const totalChart = new Chart(document.getElementById('totalMemoryChart'), {\\n                    type: 'line',\\n                    data: {\\n                        labels: lineLabels,\\n                        datasets: [{\\n                            label: 'Total Memory Usage',\\n                            data: totalSizes,\\n                            fill: false,\\n                            borderColor: 'rgba(75, 192, 192, 1)',\\n                            tension: 0.1,\\n                            pointBackgroundColor: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 'rgba(255, 99, 132, 1)' : 'rgba(75, 192, 192, 1)',\\n                            pointRadius: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 7 : 4,\\n                            pointBorderWidth: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 3 : 1\\n                        }]\\n                    },\\n                    options: {\\n                        responsive: true,\\n                        maintainAspectRatio: false,\\n                        plugins: {\\n                            title: { display: true, text: 'Total Memory Usage Over Time (Click to select, Shift+Click to compare)' },\\n                            tooltip: { callbacks: { label: context =&gt; `Total: ${formatBytes(context.raw)}` } }\\n                        },\\n                        onClick: (evt, elements) =&gt; {\\n                            if (elements.length &gt; 0) {\\n                                const idx = elements[0].index;\\n                                const isSelected = selectedIndexes.includes(idx);\\n                                if (evt.native.shiftKey) {\\n                                    if (isSelected) {\\n                                        selectedIndexes = selectedIndexes.filter(i =&gt; i !== idx);\\n                                    } else {\\n                                        selectedIndexes.push(idx);\\n                                        if (selectedIndexes.length &gt; 2) selectedIndexes.shift();\\n                                    }\\n                                } else {\\n                                    selectedIndexes = isSelected &amp;&amp; selectedIndexes.length === 1 ? [] : [idx];\\n                                }\\n                            } else {\\n                                selectedIndexes = [];\\n                            }\\n                            updateBarChart();\\n                        },\\n                        scales: {\\n                            y: { beginAtZero: true, ticks: { callback: formatBytes }, title: { display: true, text: 'Total Memory' } },\\n                            x: { title: { display: true, text: 'Time' } }\\n                        }\\n                    }\\n                });\\n\\n                const breakdownChart = new Chart(document.getElementById('memoryChart'), {\\n                    type: 'bar',\\n                    data: { labels: [], datasets: [] },\\n                    options: {\\n                        indexAxis: 'y',\\n                        responsive: true,\\n                        maintainAspectRatio: false,\\n                        layout: { padding: { right: 120 } },\\n                        plugins: {\\n                            legend: { display: false },\\n                            title: { display: true, text: 'Memory Breakdown' },\\n                            tooltip: { callbacks: { label: context =&gt; `${formatBytes(context.raw)}` } },\\n                            datalabels: {\\n                                anchor: 'end',\\n                                align: 'right',\\n                                color: '#000',\\n                                font: { weight: 'bold', size: 11 },\\n                                formatter: (value) =&gt; formatBytes(value),\\n                                display: true,\\n                                clip: false\\n                            }\\n                        },\\n                        onClick: (evt, elements) =&gt; {\\n                            if (elements.length &gt; 0 &amp;&amp; currentBreakdownData.length &gt; 0) {\\n                                const item = currentBreakdownData[elements[0].index];\\n                                const fullKey = item.fullTracebackKey || getFullTracebackKey(item.traceback);\\n                                showTraceback(item.traceback, Math.abs(item.diff || item.size), fullKey);\\n                            }\\n                        },\\n                        scales: {\\n                            x: { beginAtZero: false, ticks: { callback: formatBytes }, title: { display: true, text: 'Memory Usage / Difference' } },\\n                            y: { title: { display: true, text: 'File:Line' }, ticks: { maxRotation: 0, font: { size: 11 } } }\\n                        }\\n                    },\\n                    plugins: [ChartDataLabels]\\n                });\\n\\n                // Initial render\\n                updateBarChart();\\n            </script>\\n        </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.view_memory">\n        &lt;!DOCTYPE html&gt;\n        <html lang="en">\n        <head>\n            <meta charset="UTF-8"/>\n            <meta name="viewport" content="width=device-width, initial-scale=1.0"/>\n            <title>Memory Usage Visualization</title>\n            <script src="https://cdn.jsdelivr.net/npm/chart.js"/>\n            <script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels"/>\n            <style>\n                /* General body and layout styles */\n                body {\n                    font-family: Arial, sans-serif;\n                    margin: 20px;\n                    background-color: #f9f9f9;\n                }\n                .container {\n                    display: flex;\n                    flex-direction: column;\n                    gap: 20px;\n                }\n\n                /* Row definitions for the new layout */\n                .top-row {\n                    height: 40vh; /* Line graph takes 40% of the viewport height */\n                }\n                .bottom-row {\n                    display: flex;\n                    gap: 20px;\n                    /* The height of this row will be determined by its content */\n                }\n\n                /* Chart container styles */\n                .chart-container {\n                    position: relative;\n                    background: #fff;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                    padding: 15px;\n                    height: 100%;\n                    width: 100%;\n                }\n                \n                /* Specific styling for the bottom row elements */\n                .bar-chart-wrapper {\n                    flex: 2; /* Bar chart takes 2/3 of the width */\n                    min-height: 400px; /* Minimum height for the bar chart */\n                }\n                .traceback-panel {\n                    flex: 1; /* Traceback panel takes 1/3 of the width */\n                    background: #f5f5f5;\n                    border: 1px solid #ddd;\n                    border-radius: 5px;\n                    padding: 15px;\n                    overflow-y: auto;\n                    min-height: 400px; /* Match min-height for alignment */\n                    height: fit-content; /* Adjust height to content */\n                }\n\n                /* Traceback panel content styling */\n                .traceback-header {\n                    font-weight: bold;\n                    margin-bottom: 10px;\n                    color: #333;\n                }\n                .traceback-item {\n                    background: white;\n                    margin: 5px 0;\n                    padding: 8px;\n                    border-radius: 3px;\n                    border-left: 3px solid #007acc;\n                    font-family: monospace;\n                    font-size: 12px;\n                }\n                .traceback-file {\n                    color: #007acc;\n                    font-weight: bold;\n                }\n                .copyable {\n                    cursor: pointer;\n                    user-select: all;\n                    padding: 2px 4px;\n                    border-radius: 3px;\n                    transition: background-color 0.2s;\n                }\n                .copyable:hover {\n                    background-color: #e8f4f8;\n                }\n                .traceback-line {\n                    color: #666;\n                }\n                .no-selection {\n                    color: #999;\n                    font-style: italic;\n                    text-align: center;\n                    padding-top: 50px;\n                }\n            </style>\n        </head>\n        <body>\n            <div class="container">\n                <!-- Top row for the full-width line chart -->\n                <div class="top-row">\n                    <div class="chart-container">\n                        <canvas id="totalMemoryChart"/>\n                    </div>\n                </div>\n                <!-- Bottom row for the bar chart and traceback panel -->\n                <div class="bottom-row">\n                    <div class="bar-chart-wrapper chart-container" id="memoryChartContainer">\n                        <canvas id="memoryChart"/>\n                    </div>\n                    <div class="traceback-panel" id="tracebackPanel">\n                        <div class="no-selection">Click a point on the top chart, then a bar below to see details.</div>\n                    </div>\n                </div>\n            </div>\n\n            <script>\n                // Get data from Odoo template\n                const rawData = JSON.parse(atob('<t t-esc="memory_graph"/>'));\n\n                // --- UTILITY FUNCTIONS ---\n                function formatBytes(bytes) {\n                    if (bytes === 0) return '0 B';\n                    const k = 1024;\n                    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\n                    const i = Math.floor(Math.log(Math.abs(bytes)) / Math.log(k));\n                    const value = bytes / Math.pow(k, i);\n                    return `${value.toFixed(1)} ${sizes[i]}`;\n                }\n\n                function formatTimestamp(timestamp) {\n                    const date = new Date(timestamp * 1000);\n                    return date.toLocaleString();\n                }\n\n                function getLastFileFromTraceback(traceback) {\n                    if (!traceback || traceback.length === 0) return "unknown:0";\n                    const lastFrame = traceback[traceback.length - 1];\n                    return `${lastFrame[0]}:${lastFrame[1]}`;\n                }\n                \n                function getFullTracebackKey(traceback) {\n                    if (!traceback || traceback.length === 0) return "unknown";\n                    return traceback.map(frame =&gt; `${frame[0]}:${frame[1]}`).join(' -&gt; ');\n                }\n\n                // --- DYNAMIC UI UPDATES ---\n                function updateChartHeight(chart, dataLength) {\n                    const container = document.getElementById('memoryChartContainer');\n                    if (dataLength === 0) {\n                        container.style.height = '400px'; // Reset to min-height\n                        chart.resize();\n                        return;\n                    }\n                    \n                    const minBarHeight = 35; // Minimum height per bar for readability\n                    const padding = 100; // Extra space for axes and labels\n                    const newHeight = Math.max(400, (dataLength * minBarHeight) + padding);\n                    \n                    container.style.height = newHeight + 'px';\n                    chart.resize();\n                }\n\n                function showTraceback(traceback, size, fullTracebackKey) {\n                    const panel = document.getElementById('tracebackPanel');\n                    if (!traceback || traceback.length === 0) {\n                        panel.innerHTML = '<div class="no-selection">No traceback available</div>';\n                        return;\n                    }\n\n                    let html = `<div class="traceback-header">Traceback (${formatBytes(size)})</div>`;\n\n                    if (fullTracebackKey) {\n                        html += `\n                            <div style="margin-bottom: 10px; padding: 8px; background: #e8f4f8; border-radius: 3px; font-size: 11px; color: #555;">\n                                <strong>Full Path:</strong> <span class="copyable" title="Click to select for copying">${fullTracebackKey}</span>\n                            </div>\n                        `;\n                    }\n\n                    traceback.forEach(frame =&gt; {\n                        const [filename, lineNo, functionName, code] = frame;\n                        html += `\n                            <div class="traceback-item">\n                                <div class="traceback-file copyable" title="Click to select for copying">${filename}:${lineNo}</div>\n                                <div>in <strong>${functionName || 'unknown'}</strong></div>\n                                ${code ? `<div class="traceback-line">${code}</div>` : ''}\n                            </div>\n                        `;\n                    });\n\n                    panel.innerHTML = html;\n                }\n\n                // --- CHART LOGIC ---\n                const totalSizes = rawData.map(entry =&gt;\n                    entry.samples.reduce((sum, sample) =&gt; sum + sample.size, 0)\n                );\n                const lineLabels = rawData.map(entry =&gt; formatTimestamp(entry.start));\n\n                let selectedIndexes = [];\n                let currentBreakdownData = [];\n\n                const updateBarChart = () =&gt; {\n                    if (selectedIndexes.length === 1) {\n                        const entry = rawData[selectedIndexes[0]];\n                        const groupedData = {};\n                        entry.samples.forEach(sample =&gt; {\n                            const key = getLastFileFromTraceback(sample.traceback);\n                            if (!groupedData[key]) {\n                                groupedData[key] = { size: 0, traceback: sample.traceback, samples: [] };\n                            }\n                            groupedData[key].size += sample.size;\n                            groupedData[key].samples.push(sample);\n                        });\n\n                        currentBreakdownData = Object.entries(groupedData).map(([key, data]) =&gt; ({\n                            label: key,\n                            size: data.size,\n                            traceback: data.traceback,\n                            samples: data.samples\n                        })).sort((a, b) =&gt; b.size - a.size);\n\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\n                        breakdownChart.data.datasets = [{\n                            label: `Memory Usage`,\n                            data: currentBreakdownData.map(item =&gt; item.size),\n                            backgroundColor: 'rgba(54, 162, 235, 0.6)',\n                            borderColor: 'rgba(54, 162, 235, 1)',\n                            borderWidth: 1\n                        }];\n                        breakdownChart.options.plugins.title.text = `Memory Breakdown for ${formatTimestamp(entry.start)}`;\n\n                    } else if (selectedIndexes.length === 2) {\n                        const [idx1, idx2] = selectedIndexes.sort((a, b) =&gt; a - b);\n                        const entry1 = rawData[idx1];\n                        const entry2 = rawData[idx2];\n\n                        const groupDataByFullTraceback = (entry) =&gt; {\n                            const grouped = {};\n                            entry.samples.forEach(sample =&gt; {\n                                const key = getFullTracebackKey(sample.traceback);\n                                if (!grouped[key]) {\n                                    grouped[key] = { size: 0, traceback: sample.traceback, lastFile: getLastFileFromTraceback(sample.traceback) };\n                                }\n                                grouped[key].size += sample.size;\n                            });\n                            return grouped;\n                        };\n\n                        const data1 = groupDataByFullTraceback(entry1);\n                        const data2 = groupDataByFullTraceback(entry2);\n                        const labelSet = new Set([...Object.keys(data1), ...Object.keys(data2)]);\n                        \n                        let diffData = [];\n                        labelSet.forEach(fullTracebackKey =&gt; {\n                            const size1 = data1[fullTracebackKey]?.size || 0;\n                            const size2 = data2[fullTracebackKey]?.size || 0;\n                            const diff = size2 - size1;\n                            if (diff !== 0) {\n                                const item = data2[fullTracebackKey] || data1[fullTracebackKey];\n                                diffData.push({ \n                                    label: item.lastFile,\n                                    diff: diff,\n                                    traceback: item.traceback,\n                                    fullTracebackKey: fullTracebackKey\n                                });\n                            }\n                        });\n\n                        currentBreakdownData = diffData.sort((a, b) =&gt; b.diff - a.diff);\n\n                        breakdownChart.data.labels = currentBreakdownData.map(item =&gt; item.label);\n                        breakdownChart.data.datasets = [{\n                            label: `Difference`,\n                            data: currentBreakdownData.map(item =&gt; item.diff),\n                            backgroundColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 0.6)' : 'rgba(255, 99, 132, 0.6)',\n                            borderColor: item =&gt; item.raw &gt;= 0 ? 'rgba(75, 192, 192, 1)' : 'rgba(255, 99, 132, 1)',\n                            borderWidth: 1\n                        }];\n                        breakdownChart.options.plugins.title.text = `Memory Difference: ${formatTimestamp(entry2.start)} vs ${formatTimestamp(entry1.start)}`;\n\n                    } else {\n                        currentBreakdownData = [];\n                        breakdownChart.data.labels = [];\n                        breakdownChart.data.datasets = [];\n                        breakdownChart.options.plugins.title.text = 'Memory Breakdown';\n                        document.getElementById('tracebackPanel').innerHTML = \n                            '<div class="no-selection">Click a point on the top chart, then a bar below to see details.</div>';\n                    }\n                    \n                    updateChartHeight(breakdownChart, currentBreakdownData.length);\n                    breakdownChart.update();\n                    totalChart.update();\n                };\n\n                // --- CHART INSTANTIATION ---\n                const totalChart = new Chart(document.getElementById('totalMemoryChart'), {\n                    type: 'line',\n                    data: {\n                        labels: lineLabels,\n                        datasets: [{\n                            label: 'Total Memory Usage',\n                            data: totalSizes,\n                            fill: false,\n                            borderColor: 'rgba(75, 192, 192, 1)',\n                            tension: 0.1,\n                            pointBackgroundColor: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 'rgba(255, 99, 132, 1)' : 'rgba(75, 192, 192, 1)',\n                            pointRadius: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 7 : 4,\n                            pointBorderWidth: ctx =&gt; selectedIndexes.includes(ctx.dataIndex) ? 3 : 1\n                        }]\n                    },\n                    options: {\n                        responsive: true,\n                        maintainAspectRatio: false,\n                        plugins: {\n                            title: { display: true, text: 'Total Memory Usage Over Time (Click to select, Shift+Click to compare)' },\n                            tooltip: { callbacks: { label: context =&gt; `Total: ${formatBytes(context.raw)}` } }\n                        },\n                        onClick: (evt, elements) =&gt; {\n                            if (elements.length &gt; 0) {\n                                const idx = elements[0].index;\n                                const isSelected = selectedIndexes.includes(idx);\n                                if (evt.native.shiftKey) {\n                                    if (isSelected) {\n                                        selectedIndexes = selectedIndexes.filter(i =&gt; i !== idx);\n                                    } else {\n                                        selectedIndexes.push(idx);\n                                        if (selectedIndexes.length &gt; 2) selectedIndexes.shift();\n                                    }\n                                } else {\n                                    selectedIndexes = isSelected &amp;&amp; selectedIndexes.length === 1 ? [] : [idx];\n                                }\n                            } else {\n                                selectedIndexes = [];\n                            }\n                            updateBarChart();\n                        },\n                        scales: {\n                            y: { beginAtZero: true, ticks: { callback: formatBytes }, title: { display: true, text: 'Total Memory' } },\n                            x: { title: { display: true, text: 'Time' } }\n                        }\n                    }\n                });\n\n                const breakdownChart = new Chart(document.getElementById('memoryChart'), {\n                    type: 'bar',\n                    data: { labels: [], datasets: [] },\n                    options: {\n                        indexAxis: 'y',\n                        responsive: true,\n                        maintainAspectRatio: false,\n                        layout: { padding: { right: 120 } },\n                        plugins: {\n                            legend: { display: false },\n                            title: { display: true, text: 'Memory Breakdown' },\n                            tooltip: { callbacks: { label: context =&gt; `${formatBytes(context.raw)}` } },\n                            datalabels: {\n                                anchor: 'end',\n                                align: 'right',\n                                color: '#000',\n                                font: { weight: 'bold', size: 11 },\n                                formatter: (value) =&gt; formatBytes(value),\n                                display: true,\n                                clip: false\n                            }\n                        },\n                        onClick: (evt, elements) =&gt; {\n                            if (elements.length &gt; 0 &amp;&amp; currentBreakdownData.length &gt; 0) {\n                                const item = currentBreakdownData[elements[0].index];\n                                const fullKey = item.fullTracebackKey || getFullTracebackKey(item.traceback);\n                                showTraceback(item.traceback, Math.abs(item.diff || item.size), fullKey);\n                            }\n                        },\n                        scales: {\n                            x: { beginAtZero: false, ticks: { callback: formatBytes }, title: { display: true, text: 'Memory Usage / Difference' } },\n                            y: { title: { display: true, text: 'File:Line' }, ticks: { maxRotation: 0, font: { size: 11 } } }\n                        }\n                    },\n                    plugins: [ChartDataLabels]\n                });\n\n                // Initial render\n                updateBarChart();\n            </script>\n        </body>\n        </html>\n    </t>\n	f	t	2026-05-21 05:52:48.487522	2026-05-21 05:52:48.487522	\N
222	16	\N	1	1	config_speedscope_index	\N	web.config_speedscope_index	qweb	web/views/speedscope_config_wizard.xml	primary	{"en_US": "<t t-name=\\"web.config_speedscope_index\\">\\n        <link rel=\\"stylesheet\\" href=\\"/web/assets/any/web.assets_web.min.css\\"/>\\n        <script src=\\"/web/assets/any/web.assets_web.min.js\\" type=\\"text/javascript\\"/>\\n        <div class=\\"container-md p-0\\">\\n            <div class=\\"o_form_view align-items-center\\">\\n                <div class=\\"row\\">\\n                    <div class=\\"col\\" t-if=\\"profiles._compute_has_memory()\\">\\n                        <div class=\\"o_form_sheet\\">\\n                            <form method=\\"get\\" t-attf-action=\\"/web/profile_config/{{profile_str}}\\">\\n                                <h4>Memory profile</h4>\\n                                <div class=\\"mt-3\\">\\n                                    <label for=\\"memory_limit\\">Memory limit (in bytes)</label>\\n                                    <input type=\\"number\\" id=\\"memory_limit\\" name=\\"memory_limit\\" class=\\"form-control\\" value=\\"1000\\"/>\\n                                </div>\\n\\n                                <input type=\\"hidden\\" name=\\"profile_id\\" t-att-value=\\"profile_str\\"/>\\n                                \\n                                <div class=\\"mt-3\\">\\n                                    <button type=\\"submit\\" class=\\"btn btn-primary\\" name=\\"action\\" value=\\"memory_open\\">open</button>\\n                                </div>\\n                            </form>\\n                        </div>\\n                    </div>\\n\\n                    <div class=\\"col\\">\\n                        <div class=\\"o_form_sheet\\">\\n                            <!-- Single Form -->\\n                            <form method=\\"get\\" t-attf-action=\\"/web/speedscope/{{profile_str}}\\">\\n                                <h4>Speedscope</h4>\\n                                <div class=\\"form-check\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"constant_time\\" name=\\"constant_time\\" value=\\"True\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"constant_time\\">Constant Time</label>\\n                                </div>\\n                                <!-- add more variable here -->\\n                                <div class=\\"form-check\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"aggregate_sql\\" name=\\"aggregate_sql\\" value=\\"True\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"aggregate_sql\\">Aggregate SQL</label>\\n                                </div>\\n                                <div class=\\"form-check\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"use_execution_context\\" name=\\"use_execution_context\\" value=\\"True\\" checked=\\"1\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"use_execution_context\\">Use execution context</label>\\n                                </div>\\n                                <div t-if=\\"len(profiles) &gt; 1\\">\\n                                <hr/>\\n                                <h4>Multiple profile</h4>\\n                                    <label class=\\"form-check-label\\" for=\\"profile_aggregation_mode\\">Aggregation mode</label>\\n                                    <select class=\\"form-select\\" name=\\"profile_aggregation_mode\\" id=\\"profile_aggregation_mode\\">\\n                                        <option value=\\"tabs\\">Separated (one per tab)</option>\\n                                        <option value=\\"temporal\\">Temporal (experimental)</option>\\n                                    </select>\\n                                    <span id=\\"temporal_warning\\" class=\\"alert alert-warning\\" style=\\"display:none\\"><b>Warning:</b> Temporal mode will merge all samples.<br/>It can lead to partially invalid result in case of concurrent profiles.<br/>Use with caution </span>\\n                                    <script>\\n                                        document.getElementById('profile_aggregation_mode').addEventListener('change', function (event) {\\n                                            document.getElementById('temporal_warning').style.display = event.target.value === 'temporal'? 'block': 'none';\\n                                        });\\n                                    </script>\\n\\n                                </div>\\n                                <hr/>\\n                                <h4>Display presets</h4>\\n                                <t t-set=\\"has_sql\\" t-value=\\"any(profile.sql for profile in profiles)\\"/>\\n                                <t t-set=\\"has_traces\\" t-value=\\"any(profile.traces_async for profile in profiles)\\"/>\\n                                <div class=\\"form-check\\" t-if=\\"has_sql and has_traces\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"combined_profile\\" name=\\"combined_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('combined_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"combined_profile\\">Frames + sql (Combined)</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_sql\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"sql_no_gap_profile\\" name=\\"sql_no_gap_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('sql_no_gap_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"sql_no_gap_profile\\">SQL no gap</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_sql\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"sql_density_profile\\" name=\\"sql_density_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('sql_density_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"sql_density_profile\\">SQL density</label>\\n                                </div>\\n                                <div class=\\"form-check\\" t-if=\\"has_traces\\">\\n                                    <input type=\\"checkbox\\" class=\\"form-check-input\\" id=\\"frames_profile\\" name=\\"frames_profile\\" value=\\"True\\" t-att-checked=\\"default_params.get('frames_profile')\\"/>\\n                                    <label class=\\"form-check-label\\" for=\\"frames_profile\\">Frames</label>\\n                                </div>\\n\\n                                <input type=\\"hidden\\" name=\\"profile_id\\" t-att-value=\\"profile_str\\"/>\\n                                \\n                                <div class=\\"mt-3\\">\\n                                    <button type=\\"submit\\" class=\\"btn btn-secondary\\" name=\\"action\\" value=\\"speedscope_download_json\\"><i class=\\"fa fa-download\\"/> (json)</button>\\n                                    <button type=\\"submit\\" class=\\"btn btn-secondary\\" name=\\"action\\" value=\\"speedscope_download_html\\"><i class=\\"fa fa-download\\"/> (html)</button>\\n                                    <button type=\\"submit\\" class=\\"btn btn-primary\\" name=\\"action\\" value=\\"speedscope_open\\">Open</button>\\n                                </div>\\n                            </form>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.config_speedscope_index">\n        <link rel="stylesheet" href="/web/assets/any/web.assets_web.min.css"/>\n        <script src="/web/assets/any/web.assets_web.min.js" type="text/javascript"/>\n        <div class="container-md p-0">\n            <div class="o_form_view align-items-center">\n                <div class="row">\n                    <div class="col" t-if="profiles._compute_has_memory()">\n                        <div class="o_form_sheet">\n                            <form method="get" t-attf-action="/web/profile_config/{{profile_str}}">\n                                <h4>Memory profile</h4>\n                                <div class="mt-3">\n                                    <label for="memory_limit">Memory limit (in bytes)</label>\n                                    <input type="number" id="memory_limit" name="memory_limit" class="form-control" value="1000"/>\n                                </div>\n\n                                <input type="hidden" name="profile_id" t-att-value="profile_str"/>\n                                \n                                <div class="mt-3">\n                                    <button type="submit" class="btn btn-primary" name="action" value="memory_open">open</button>\n                                </div>\n                            </form>\n                        </div>\n                    </div>\n\n                    <div class="col">\n                        <div class="o_form_sheet">\n                            <!-- Single Form -->\n                            <form method="get" t-attf-action="/web/speedscope/{{profile_str}}">\n                                <h4>Speedscope</h4>\n                                <div class="form-check">\n                                    <input type="checkbox" class="form-check-input" id="constant_time" name="constant_time" value="True"/>\n                                    <label class="form-check-label" for="constant_time">Constant Time</label>\n                                </div>\n                                <!-- add more variable here -->\n                                <div class="form-check">\n                                    <input type="checkbox" class="form-check-input" id="aggregate_sql" name="aggregate_sql" value="True"/>\n                                    <label class="form-check-label" for="aggregate_sql">Aggregate SQL</label>\n                                </div>\n                                <div class="form-check">\n                                    <input type="checkbox" class="form-check-input" id="use_execution_context" name="use_execution_context" value="True" checked="1"/>\n                                    <label class="form-check-label" for="use_execution_context">Use execution context</label>\n                                </div>\n                                <div t-if="len(profiles) &gt; 1">\n                                <hr/>\n                                <h4>Multiple profile</h4>\n                                    <label class="form-check-label" for="profile_aggregation_mode">Aggregation mode</label>\n                                    <select class="form-select" name="profile_aggregation_mode" id="profile_aggregation_mode">\n                                        <option value="tabs">Separated (one per tab)</option>\n                                        <option value="temporal">Temporal (experimental)</option>\n                                    </select>\n                                    <span id="temporal_warning" class="alert alert-warning" style="display:none"><b>Warning:</b> Temporal mode will merge all samples.<br/>It can lead to partially invalid result in case of concurrent profiles.<br/>Use with caution </span>\n                                    <script>\n                                        document.getElementById('profile_aggregation_mode').addEventListener('change', function (event) {\n                                            document.getElementById('temporal_warning').style.display = event.target.value === 'temporal'? 'block': 'none';\n                                        });\n                                    </script>\n\n                                </div>\n                                <hr/>\n                                <h4>Display presets</h4>\n                                <t t-set="has_sql" t-value="any(profile.sql for profile in profiles)"/>\n                                <t t-set="has_traces" t-value="any(profile.traces_async for profile in profiles)"/>\n                                <div class="form-check" t-if="has_sql and has_traces">\n                                    <input type="checkbox" class="form-check-input" id="combined_profile" name="combined_profile" value="True" t-att-checked="default_params.get('combined_profile')"/>\n                                    <label class="form-check-label" for="combined_profile">Frames + sql (Combined)</label>\n                                </div>\n                                <div class="form-check" t-if="has_sql">\n                                    <input type="checkbox" class="form-check-input" id="sql_no_gap_profile" name="sql_no_gap_profile" value="True" t-att-checked="default_params.get('sql_no_gap_profile')"/>\n                                    <label class="form-check-label" for="sql_no_gap_profile">SQL no gap</label>\n                                </div>\n                                <div class="form-check" t-if="has_sql">\n                                    <input type="checkbox" class="form-check-input" id="sql_density_profile" name="sql_density_profile" value="True" t-att-checked="default_params.get('sql_density_profile')"/>\n                                    <label class="form-check-label" for="sql_density_profile">SQL density</label>\n                                </div>\n                                <div class="form-check" t-if="has_traces">\n                                    <input type="checkbox" class="form-check-input" id="frames_profile" name="frames_profile" value="True" t-att-checked="default_params.get('frames_profile')"/>\n                                    <label class="form-check-label" for="frames_profile">Frames</label>\n                                </div>\n\n                                <input type="hidden" name="profile_id" t-att-value="profile_str"/>\n                                \n                                <div class="mt-3">\n                                    <button type="submit" class="btn btn-secondary" name="action" value="speedscope_download_json"><i class="fa fa-download"/> (json)</button>\n                                    <button type="submit" class="btn btn-secondary" name="action" value="speedscope_download_html"><i class="fa fa-download"/> (html)</button>\n                                    <button type="submit" class="btn btn-primary" name="action" value="speedscope_open">Open</button>\n                                </div>\n                            </form>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </t>\n	f	t	2026-05-21 05:52:48.487522	2026-05-21 05:52:48.487522	\N
