395	16	\N	1	1	message_origin_link	\N	mail.message_origin_link	qweb	mail/data/mail_templates_chatter.xml	primary	{"en_US": "<t t-name=\\"mail.message_origin_link\\">\\n            <p>\\n                <t t-if=\\"edit\\">This <t t-esc=\\"self.env['ir.model']._get(self._name).name.lower()\\"/> has been modified from:</t>\\n                <t t-else=\\"\\">This <t t-esc=\\"self.env['ir.model']._get(self._name).name.lower()\\"/> has been created from:</t>\\n                <t t-foreach=\\"origin\\" t-as=\\"o\\">\\n                    <a href=\\"#\\" t-att-data-oe-model=\\"o._name\\" t-att-data-oe-id=\\"o.id\\"> <t t-esc=\\"o.display_name\\"/></a><span t-if=\\"origin.ids[-1:] != o.ids\\">, </span>\\n                </t>\\n            </p>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="mail.message_origin_link">\n            <p>\n                <t t-if="edit">This <t t-esc="self.env['ir.model']._get(self._name).name.lower()"/> has been modified from:</t>\n                <t t-else="">This <t t-esc="self.env['ir.model']._get(self._name).name.lower()"/> has been created from:</t>\n                <t t-foreach="origin" t-as="o">\n                    <a href="#" t-att-data-oe-model="o._name" t-att-data-oe-id="o.id"> <t t-esc="o.display_name"/></a><span t-if="origin.ids[-1:] != o.ids">, </span>\n                </t>\n            </p>\n        </t>\n\n        	f	t	2026-05-21 05:54:04.21157	2026-05-21 05:54:04.21157	\N
396	16	\N	1	1	discuss_channel_invitation_template	\N	mail.discuss_channel_invitation_template	qweb	mail/data/mail_templates_chatter.xml	primary	{"en_US": "<t t-name=\\"mail.discuss_channel_invitation_template\\">\\n            <div style=\\"padding: 16px; background-color: #F1F1F1; font-family: Verdana, Arial, sans-serif; color: #454748; width: 100%; display: flex; justify-content: center;\\">\\n                <div style=\\"max-width: 590px; width: 100%; background-color: #ffffff; border-radius: 8px; padding: 20px; display: flex; flex-direction: column; align-items: center;\\">\\n                    <div style=\\"width: 100%; font-size: 14px; line-height: 1.5; text-align: left;\\">\\n                        <t t-esc=\\"mail_body\\"/>\\n                        <p style=\\"text-align: center; margin: 24px 0;\\">\\n                            <a t-attf-href=\\"{{base_url}}{{channel.invitation_url}}?email_token={{email_token}}\\" t-attf-style=\\"background-color: {{user.company_id.email_secondary_color or '#875A7B'}}; color: {{user.company_id.email_primary_color or '#FFFFFF'}}; text-decoration: none; padding: 8px 12px; border-radius: 4px; display: inline-block; font-weight: bold;\\">\\n                                Join Channel\\n                            </a>\\n                        </p>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="mail.discuss_channel_invitation_template">\n            <div style="padding: 16px; background-color: #F1F1F1; font-family: Verdana, Arial, sans-serif; color: #454748; width: 100%; display: flex; justify-content: center;">\n                <div style="max-width: 590px; width: 100%; background-color: #ffffff; border-radius: 8px; padding: 20px; display: flex; flex-direction: column; align-items: center;">\n                    <div style="width: 100%; font-size: 14px; line-height: 1.5; text-align: left;">\n                        <t t-esc="mail_body"/>\n     