rrent_customer()"/>\n                    <t t-set="selected" t-value="address == selected_address"/>\n                    <t t-set="show_removal" t-value="can_be_edited and not selected and not is_user_address"/>\n                </t>\n            </t>\n        </div>\n    </t>\n\n    	f	t	2026-05-21 05:54:26.128055	2026-05-21 05:54:26.128055	f
