686	16	\N	1	1	availability_report_records	\N	payment.availability_report_records	qweb	payment/views/payment_form_templates.xml	primary	{"en_US": "<t t-name=\\"payment.availability_report_records\\">\\n        <!-- Parameters description:\\n            - records: The records to list in the availability report, as a dict with the structure\\n                       {record: {'available': bool, 'reason': str, supported_providers: list}}.\\n        -->\\n        <ul class=\\"list-group\\">\\n            <t t-foreach=\\"records\\" t-as=\\"r\\">\\n                <t t-set=\\"available\\" t-value=\\"records[r]['available']\\"/>\\n                <li class=\\"list-group-item ps-0\\">\\n                    <div class=\\"d-flex gap-2\\">\\n                        <div class=\\"ms-2\\">\\n                            <i t-attf-class=\\"fa fa-fw fa-{{'check-circle' if available else 'times-circle'}}\\" t-attf-style=\\"color: {{'green' if available else 'red'}};\\"/>\\n                        </div>\\n                        <div>\\n                            <p class=\\"lead mb-0\\">\\n                                <span class=\\"fw-normal\\"><t t-out=\\"r.name\\"/></span>\\n                                <span class=\\"text-muted\\">(ID: <t t-out=\\"r.id\\"/>)</span>\\n                            </p>\\n                            <t t-if=\\"not available\\">\\n                                <p class=\\"mb-0 fw-light\\">\\n                                    Reason: <t t-out=\\"records[r]['reason']\\"/>\\n                                </p>\\n                            </t>\\n                            <t t-if=\\"r._name == 'payment.method' and 'supported_providers' in records[r]\\">\\n                                <p class=\\"mb-0 fw-light\\">\\n                                    Supported providers:\\n                                     <t t-foreach=\\"records[r]['supported_providers']\\" t-as=\\"p\\">\\n                                        <span t-attf-class=\\"text-{{'success' if p[1] else 'danger'}}\\">\\n                                            <t t-out=\\"p[0].name\\"/>\\n                                        </span>\\n                                        <t t-if=\\"records[r]['supported_providers'][-1] != p\\">,</t>\\n                                    </t>\\n                                </p>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </li>\\n            </t>\\n        </ul>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.availability_report_records">\n        <!-- Parameters description:\n            - records: The records to list in the availability report, as a dict with the structure\n                       {record: {'available': bool, 'reason': str, supported_providers: list}}.\n        -->\n        <ul class="list-group">\n            <t t-foreach="records" t-as="r">\n                <t t-set="available" t-value="records[r]['available']"/>\n                <li class="list-group-item ps-0">\n                    <div class="d-flex gap-2">\n                        <div class="ms-2">\n                            <i t-attf-class="fa fa-fw fa-{{'check-circle' if available else 'times-circle'}}" t-attf-style="color: {{'green' if available else 'red'}};"/>\n                        </div>\n                        <div>\n                            <p class="lead mb-0">\n                                <span class="fw-normal"><t t-out="r.name"/></span>\n                                <span class="text-muted">(ID: <t t-out="r.id"/>)</span>\n                            </p>\n                            <t t-if="not available">\n                                <p class="mb-0 fw-light">\n                                    Reason: <t t-out="records[r]['reason']"/>\n                                </p>\n                            </t>\n                            <t t-if="r._name == 'payment.method' and 'supported_providers' in records[r]">\n                                <p class="mb-0 fw-light">\n                                    Supported providers:\n                                     <t t-foreach="records[r]['supported_providers']" t-as="p">\n                                        <span t-attf-class="text-{{'success' if p[1] else 'danger'}}">\n                                            <t t-out="p[0].name"/>\n                                        </span>\n                                        <t t-if="records[r]['supported_providers'][-1] != p">,</t>\n                                    </t>\n                                </p>\n                            </t>\n                        </div>\n                    </div>\n                </li>\n            </t>\n        </ul>\n    </t>\n\n	f	t	2026-05-21 05:54:30.617438	2026-05-21 05:54:30.617438	f
687	16	\N	1	1	payment.pay	\N	payment.pay	qweb	payment/views/portal_templates.xml	primary	{"en_US": "<t t-name=\\"payment.pay\\">\\n        <!-- Parameters description:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - availability_report: The availability report of providers and payment methods.\\n            - res_company: The company in which the payment if made (for the company logo).\\n            - company_mismatch: Whether the user should make the payment in another company.\\n            - expected_company: The record of the company that the user should switch to.\\n            - partner_is_different: Whether the partner logged in is the one making the payment.\\n        -->\\n        <t t-call=\\"portal.frontend_layout\\">\\n            <t t-set=\\"page_title\\">Payment</t>\\n            <t t-set=\\"additional_title\\"><t t-esc=\\"page_title\\"/></t>\\n            <div class=\\"wrap\\">\\n                <div class=\\"container\\">\\n                    <!-- Portal breadcrumb -->\\n                    <t t-call=\\"payment.portal_breadcrumb\\"/>\\n                    <!-- Payment page -->\\n                    <div class=\\"row justify-content-center my-3\\">\\n                        <div class=\\"col-lg-7\\">\\n                            <div t-if=\\"not amount\\" class=\\"alert alert-info\\">\\n                                There is nothing to pay.\\n                            </div>\\n                            <div t-elif=\\"not currency\\" class=\\"alert alert-warning\\">\\n                                <strong>Warning</strong> The currency is missing or incorrect.\\n                            </div>\\n                            <div t-elif=\\"not partner_id\\" class=\\"alert alert-warning\\">\\n                                <strong>Warning</strong> You must be logged in to pay.\\n                            </div>\\n                            <div t-elif=\\"company_mismatch\\">\\n                                <t t-call=\\"payment.company_mismatch_warning\\"/>\\n                            </div>\\n                            <t t-else=\\"\\">\\n                                <div t-if=\\"partner_is_different\\" class=\\"alert alert-warning\\">\\n                                    <strong>Warning</strong> Make sure you are logged in as the\\n                                    correct partner before making this payment.\\n                                </div>\\n                                <div class=\\"text-bg-light row row-cols-1 row-cols-md-2 mx-0 py-2                                             rounded\\">\\n                                    <t t-call=\\"payment.summary_item\\">\\n                                        <t t-set=\\"name\\" t-value=\\"'amount'\\"/>\\n                                        <t t-set=\\"label\\">Amount</t>\\n                                        <t t-set=\\"value\\" t-value=\\"amount\\"/>\\n                                        <t t-set=\\"options\\" t-value=\\"{'widget': 'monetary', 'display_currency': currency}\\"/>\\n                                    </t>\\n                                    <t t-call=\\"payment.summary_item\\">\\n                                        <t t-set=\\"name\\" t-value=\\"'reference'\\"/>\\n                                        <t t-set=\\"label\\">Reference</t>\\n                                        <t t-set=\\"value\\" t-value=\\"reference_prefix\\"/>\\n                                        <t t-set=\\"include_separator\\" t-value=\\"True\\"/>\\n                                    </t>\\n                                </div>\\n                                <div class=\\"mt-4\\">\\n                                    <t t-call=\\"payment.form\\"/>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.pay">\n        <!-- Parameters description:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - availability_report: The availability report of providers and payment methods.\n            - res_company: The company in which the payment if made (for the company logo).\n            - company_mismatch: Whether the user should make the payment in another company.\n            - expected_company: The record of the company that the user should switch to.\n            - partner_is_different: Whether the partner logged in is the one making the payment.\n        -->\n        <t t-call="portal.frontend_layout">\n            <t t-set="page_title">Payment</t>\n            <t t-set="additional_title"><t t-esc="page_title"/></t>\n            <div class="wrap">\n                <div class="container">\n                    <!-- Portal breadcrumb -->\n                    <t t-call="payment.portal_breadcrumb"/>\n                    <!-- Payment page -->\n                    <div class="row justify-content-center my-3">\n                        <div class="col-lg-7">\n                            <div t-if="not amount" class="alert alert-info">\n                                There is nothing to pay.\n                            </div>\n                            <div t-elif="not currency" class="alert alert-warning">\n                                <strong>Warning</strong> The currency is missing or incorrect.\n                            </div>\n                            <div t-elif="not partner_id" class="alert alert-warning">\n                                <strong>Warning</strong> You must be logged in to pay.\n                            </div>\n                            <div t-elif="company_mismatch">\n                                <t t-call="payment.company_mismatch_warning"/>\n                            </div>\n                            <t t-else="">\n                                <div t-if="partner_is_different" class="alert alert-warning">\n                                    <strong>Warning</strong> Make sure you are logged in as the\n                                    correct partner before making this payment.\n                                </div>\n                                <div class="text-bg-light row row-cols-1 row-cols-md-2 mx-0 py-2                                             rounded">\n                                    <t t-call="payment.summary_item">\n                                        <t t-set="name" t-value="'amount'"/>\n                                        <t t-set="label">Amount</t>\n                                        <t t-set="value" t-value="amount"/>\n                                        <t t-set="options" t-value="{'widget': 'monetary', 'display_currency': currency}"/>\n                                    </t>\n                                    <t t-call="payment.summary_item">\n                                        <t t-set="name" t-value="'reference'"/>\n                                        <t t-set="label">Reference</t>\n                                        <t t-set="value" t-value="reference_prefix"/>\n                                        <t t-set="include_separator" t-value="True"/>\n                                    </t>\n                                </div>\n                                <div class="mt-4">\n                                    <t t-call="payment.form"/>\n                                </div>\n                            </t>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>\n\n    	f	t	2026-05-21 05:54:30.617438	2026-05-21 05:54:30.617438	f
