1277	16	632	1	1	Sales Order	\N	sale.sale_order_portal_template	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<data name=\\"Sales Order\\" inherit_id=\\"portal.portal_sidebar\\" primary=\\"True\\">\\n        <t t-call=\\"portal.portal_layout\\" position=\\"inside\\">\\n            <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"sales_team.group_sale_salesman\\">\\n                <!-- Uses backend_url provided in rendering values -->\\n                <t t-call=\\"portal.portal_back_in_edit_mode\\"/>\\n            </t>\\n        </t>\\n\\n        <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n            <div class=\\"row o_portal_sale_sidebar\\" t-att-data-order-amount-total=\\"sale_order.amount_total\\">\\n                <!-- Sidebar -->\\n                <t t-call=\\"portal.portal_record_sidebar\\">\\n                    <t t-set=\\"classes\\" t-value=\\"'col-lg-4 col-xxl-3 d-print-none'\\"/>\\n                    <t t-set=\\"title\\">\\n                        <t t-if=\\"sale_order.state in 'draft,sent' and sale_order.prepayment_percent != 1.0\\">\\n                            <h4>Down payment</h4>\\n                            <h2>\\n                                <t t-out=\\"sale_order._get_prepayment_required_amount()\\" t-options=\\"{                                         'widget': 'monetary',                                         'display_currency': sale_order.currency_id,                                     }\\"/>\\n                                (<t t-out=\\"sale_order.prepayment_percent * 100\\"/>%)\\n                            </h2>\\n                        </t>\\n                        <h2 t-else=\\"\\" t-field=\\"sale_order.amount_total\\" class=\\"mb-0 text-break\\"/>\\n                    </t>\\n                    <t t-set=\\"entries\\">\\n                        <div t-if=\\"0 &lt; sale_order.amount_paid &lt; sale_order.amount_total                                   and sale_order.state != 'cancel'\\" class=\\"alert alert-success mt-3\\" role=\\"alert\\">\\n                            Amount paid:\\n                            <span t-field=\\"sale_order.amount_paid\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id,                                 }\\"/>\\n                        </div>\\n\\n                        <div class=\\"d-flex flex-column gap-4 mt-3\\">\\n                            <div class=\\"d-flex flex-column gap-2\\" id=\\"sale_order_sidebar_button\\">\\n                                <a t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" role=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\"> <!-- If paying by link, signing is skipped. -->\\n                                    <i class=\\"fa fa-check\\"/>\\n                                    <t t-if=\\"sale_order._has_to_be_paid()\\"> Sign &amp; Pay</t>\\n                                    <t t-else=\\"\\"> Accept &amp; Sign</t>\\n                                </a>\\n                                <a t-elif=\\"sale_order._has_to_be_paid()                                             or (                                                 payment_amount                                                 and sale_order.amount_paid &lt; sale_order.amount_total                                                 and sale_order.state != 'cancel'                                             )\\" id=\\"o_sale_portal_paynow\\" role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'btn btn-primary' if not sale_order.transaction_ids else 'btn btn-light'\\">\\n                                    <i class=\\"fa fa-check\\"/>\\n                                    <t t-if=\\"not sale_order.signature                                              and sale_order._has_to_be_paid()                                              and not payment_amount\\"> Accept &amp; Pay</t>\\n                                    <t t-else=\\"\\"> Pay Now</t>\\n                                </a>\\n                                <div id=\\"print_invoice_sidebar_button\\" class=\\"o_download_pdf d-flex gap-2 flex-lg-column flex-xl-row flex-wrap\\">\\n                                    <a class=\\"btn btn-light o_print_btn o_portal_invoice_print flex-grow-1\\" t-att-href=\\"sale_order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"View Details\\" role=\\"button\\" target=\\"_blank\\"><i class=\\"fa fa-print me-1\\"/>View Details</a>\\n                                </div>\\n                            </div>\\n\\n                            <div class=\\"navspy flex-grow-1 ps-0\\" t-ignore=\\"true\\" role=\\"complementary\\">\\n                                <ul class=\\"nav flex-column bs-sidenav\\"/>\\n                            </div>\\n\\n                            <t t-if=\\"not sale_order.is_expired and sale_order.state in ['draft', 'sent']\\">\\n                                <div t-if=\\"sale_order.amount_undiscounted - sale_order.amount_untaxed &gt; 0.01\\" class=\\"list-group-item flex-grow-1\\" name=\\"sale_order_advantage\\">\\n                                    <small><b class=\\"text-muted\\">Your advantage</b></small>\\n                                    <small>\\n                                        <b t-field=\\"sale_order.amount_undiscounted\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\\" style=\\"text-decoration: line-through\\" class=\\"d-block mt-1\\" data-id=\\"amount_undiscounted\\"/>\\n                                    </small>\\n                                    <t t-if=\\"sale_order.amount_untaxed == sale_order.amount_total\\">\\n                                        <h4 t-field=\\"sale_order.amount_total\\" class=\\"text-success\\" data-id=\\"total_amount\\"/>\\n                                    </t>\\n                                    <t t-else=\\"\\">\\n                                        <h4 t-field=\\"sale_order.amount_untaxed\\" class=\\"text-success mb-0\\" data-id=\\"total_untaxed\\"/>\\n                                        <small>(<span t-field=\\"sale_order.amount_total\\" data-id=\\"total_amount\\"/> Incl. tax)</small>\\n                                    </t>\\n                                </div>\\n                            </t>\\n\\n                            <div t-if=\\"sale_order.user_id\\">\\n                                <h6><small class=\\"text-muted\\">Your contact</small></h6>\\n                                <t t-call=\\"portal.portal_my_contact\\">\\n                                    <t t-set=\\"_contactAvatar\\" t-value=\\"image_data_uri(sale_order.user_id.avatar_128)\\"/>\\n                                    <t t-set=\\"_contactName\\" t-value=\\"sale_order.user_id.name\\"/>\\n                                    <t t-set=\\"_contactLink\\" t-value=\\"True\\"/>\\n                                </t>\\n                            </div>\\n\\n                            <div t-if=\\"sale_order._get_edi_builders()\\">\\n                                <button id=\\"portal_connect_software_modal_btn\\" type=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#sale_portal_connect_software_modal\\">\\n                                        Connect with your software!\\n                                </button>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </t>\\n\\n                <div class=\\"modal fade\\" id=\\"sale_portal_connect_software_modal\\" tabindex=\\"-1\\" role=\\"dialog\\" aria-hidden=\\"true\\">\\n                    <div class=\\"modal-dialog modal-lg\\" role=\\"document\\">\\n                        <div class=\\"modal-content\\">\\n                            <div class=\\"modal-body\\">\\n                                <div>\\n                                    <h5>Want to import this document in Odoo?</h5>\\n                                    <p>Drag and drop the request for quotation PDF file into your list of quotations in Odoo. Enjoy the automation!</p>\\n                                </div>\\n                                <div>\\n                                    <h5>Not using Odoo?</h5>\\n                                    <div class=\\"input-group mb-3 w-50\\">\\n                                        <t t-set=\\"base_address\\" t-value=\\"sale_order.env['ir.config_parameter'].sudo().get_param('web.base.url')\\"/>\\n                                        <t t-set=\\"doc_url\\" t-value=\\"base_address + '/my/orders/' + str(sale_order.id) + '/download_edi?' + str(keep_query())\\"/>\\n                                        <input type=\\"text\\" class=\\"form-control\\" aria-describedby=\\"copy-button\\" readonly=\\"readonly\\" t-att-value=\\"doc_url\\"/>\\n                                        <button class=\\"btn btn-outline-secondary\\" type=\\"button\\" id=\\"copy-button\\" t-attf-onclick=\\"navigator.clipboard.writeText('#{doc_url}')\\">Copy</button>\\n                                    </div>\\n                                    <p>Use the above REST URL to get structured data of the purchase order in UBL format.\\n                                        <a href=\\"https://www.odoo.com/documentation/\\">Read the documentation </a>to learn all the ways to connect your software with <a href=\\"https://www.odoo.com\\">Odoo</a>.\\n                                    </p>\\n                                </div>\\n                                <div>\\n                                    <h5>You don't use a good CRM software?</h5>\\n                                    <p><a href=\\"https://www.odoo.com/app/sales\\">Start on Odoo</a>, it's 100% free! You'll save time creating beautiful quotations and track sales.</p>\\n                                </div>\\n                            </div>\\n                            <div class=\\"modal-footer justify-content-between\\">\\n                                <button type=\\"button\\" class=\\"btn btn-secondary\\" data-bs-dismiss=\\"modal\\">Close</button>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <!-- Page content -->\\n                <div id=\\"quote_content\\" class=\\"col-12 col-lg-8 col-xxl-9 mt-5 mt-lg-0\\">\\n\\n                    <!-- Modals container -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modalaccept\\" name=\\"sale_order_modal_sign_and_pay\\">\\n                        <div t-if=\\"sale_order._has_to_be_signed() and not payment_amount\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_sign_modal\\"/></div>\\n                        <div t-elif=\\"not sale_order._has_to_be_signed()                                     and sale_order._has_to_be_paid()                                     or (payment_amount and sale_order.state != 'cancel')\\" name=\\"sale_order_modal_validate\\" class=\\"modal-dialog\\"><t t-call=\\"sale.sale_order_portal_pay_modal\\"/></div>\\n                    </div>\\n\\n                    <!-- modal relative to the action reject -->\\n                    <div role=\\"dialog\\" class=\\"modal fade\\" id=\\"modaldecline\\">\\n                        <div class=\\"modal-dialog\\">\\n                            <form id=\\"decline\\" method=\\"POST\\" t-attf-action=\\"/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}\\" class=\\"modal-content\\">\\n                                <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                                <header class=\\"modal-header\\">\\n                                    <h4 class=\\"modal-title\\">Reject This Quotation</h4>\\n                                    <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Close\\"/>\\n                                </header>\\n                                <main class=\\"modal-body\\">\\n                                    <p>\\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\\n                                    </p>\\n                                    <textarea rows=\\"4\\" name=\\"decline_message\\" required=\\"\\" placeholder=\\"Your feedback...\\" class=\\"form-control\\"/>\\n                                </main>\\n                                <footer class=\\"modal-footer\\">\\n                                    <button type=\\"submit\\" t-att-id=\\"sale_order.id\\" class=\\"btn btn-danger\\">\\n                                        <i class=\\"fa fa-times\\"/> Reject\\n                                    </button>\\n                                    <button type=\\"button\\" class=\\"btn btn-primary\\" data-bs-dismiss=\\"modal\\">\\n                                        Cancel\\n                                    </button>\\n                                </footer>\\n                            </form>\\n                        </div>\\n                    </div>\\n\\n                    <!-- status messages -->\\n                    <div t-if=\\"message == 'sign_ok'\\" class=\\"alert alert-success alert-dismissible d-print-none\\" role=\\"status\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n                        <strong>Thank You!</strong><br/>\\n                        <t t-if=\\"message == 'sign_ok' and sale_order.state == 'sale'\\">\\n                            Your order has been confirmed.\\n                        </t>\\n                        <t t-elif=\\"message == 'sign_ok' and sale_order._has_to_be_paid()\\">\\n                            Your order has been signed but still needs to be paid to be confirmed.\\n                        </t>\\n                        <t t-else=\\"\\">Your order has been signed.</t>\\n                    </div>\\n\\n                    <div t-if=\\"message == 'cant_reject'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"Close\\"/>\\n                        Your order is not in a state to be rejected.\\n                    </div>\\n\\n                    <t t-set=\\"current_tx\\" t-value=\\"sale_order.get_portal_last_transaction()\\"/>\\n                    <!-- hide state header when invoice is posted for current transaction. -->\\n                    <t t-if=\\"current_tx and not (current_tx.state == 'done' and len(current_tx.invoice_ids) == 1 and current_tx.invoice_ids.state == 'posted')\\">\\n                        <t t-call=\\"payment.state_header\\">\\n                            <t t-set=\\"tx\\" t-value=\\"current_tx\\"/>\\n                        </t>\\n                    </t>\\n\\n                    <div t-if=\\"sale_order.state == 'cancel'\\" class=\\"alert alert-danger alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"close\\"/>\\n                        <strong>This quotation has been cancelled.</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"fa fa-comment\\"/> Contact us to get a new quotation.</a>\\n                    </div>\\n\\n                    <div t-if=\\"sale_order.is_expired\\" class=\\"alert alert-warning alert-dismissible d-print-none\\" role=\\"alert\\">\\n                        <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"alert\\" aria-label=\\"close\\"/>\\n                        <strong>This offer expired!</strong> <a role=\\"button\\" href=\\"#discussion\\"><i class=\\"fa fa-comment\\"/> Contact us to get a new quotation.</a>\\n                    </div>\\n\\n                    <!-- main content -->\\n                    <div t-attf-class=\\"#{'pb-5' if report_type == 'html' else ''}\\" id=\\"portal_sale_content\\">\\n                        <div><t t-call=\\"#{sale_order._get_name_portal_content_view()}\\"/></div>\\n                    </div>\\n\\n                    <!-- bottom actions -->\\n                    <div t-if=\\"sale_order._has_to_be_signed() or sale_order._has_to_be_paid()\\" class=\\"d-flex justify-content-center gap-1 d-print-none\\" name=\\"sale_order_actions\\">\\n\\n                        <t t-if=\\"sale_order._has_to_be_signed()\\">\\n                            <div class=\\"col-sm-auto mt8\\">\\n                                <a role=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\"><i class=\\"fa fa-check\\"/><t t-if=\\"sale_order._has_to_be_paid()\\"> Sign &amp; Pay</t><t t-else=\\"\\"> Accept &amp; Sign</t></a>\\n                            </div>\\n                            <div class=\\"col-sm-auto mt8\\">\\n                                <a role=\\"button\\" class=\\"btn btn-light\\" href=\\"#discussion\\"><i class=\\"fa fa-comment\\"/> Feedback</a>\\n                            </div>\\n                            <div class=\\"col-sm-auto mt8\\">\\n                                <a role=\\"button\\" class=\\"btn btn-danger\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modaldecline\\" href=\\"#\\"> <i class=\\"fa fa-times\\"/> Reject</a>\\n                            </div>\\n                        </t>\\n                        <div t-elif=\\"sale_order._has_to_be_paid()\\" class=\\"col-sm-auto mt8\\">\\n                            <a role=\\"button\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#modalaccept\\" href=\\"#\\" t-att-class=\\"'%s' % ('btn btn-light' if sale_order.transaction_ids else 'btn btn-primary')\\">\\n                                <i class=\\"fa fa-check\\"/> <t t-if=\\"not sale_order.signature\\">Accept &amp; Pay</t><t t-else=\\"\\">Pay Now</t>\\n                            </a>\\n                        </div>\\n                    </div>\\n\\n                    <!-- chatter -->\\n                    <hr/>\\n                    <div id=\\"sale_order_communication\\">\\n                        <h3>Communication history</h3>\\n                        <t t-call=\\"portal.message_thread\\"/>\\n                    </div>\\n                </div><!-- // #quote_content -->\\n            </div>\\n        </xpath>\\n    <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">sale.sale_order_portal_template</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data name="Sales Order" inherit_id="portal.portal_sidebar" primary="True">\n        <t t-call="portal.portal_layout" position="inside">\n            <t t-set="o_portal_fullwidth_alert" groups="sales_team.group_sale_salesman">\n                <!-- Uses backend_url provided in rendering values -->\n                <t t-call="portal.portal_back_in_edit_mode"/>\n            </t>\n        </t>\n\n        <xpath expr="//div[hasclass('o_portal_sidebar')]" position="inside">\n            <div class="row o_portal_sale_sidebar" t-att-data-order-amount-total="sale_order.amount_total">\n                <!-- Sidebar -->\n                <t t-call="portal.portal_record_sidebar">\n                    <t t-set="classes" t-value="'col-lg-4 col-xxl-3 d-print-none'"/>\n                    <t t-set="title">\n                        <t t-if="sale_order.state in 'draft,sent' and sale_order.prepayment_percent != 1.0">\n                            <h4>Down payment</h4>\n                            <h2>\n                                <t t-out="sale_order._get_prepayment_required_amount()" t-options="{                                         'widget': 'monetary',                                         'display_currency': sale_order.currency_id,                                     }"/>\n                                (<t t-out="sale_order.prepayment_percent * 100"/>%)\n                            </h2>\n                        </t>\n                        <h2 t-else="" t-field="sale_order.amount_total" class="mb-0 text-break"/>\n                    </t>\n                    <t t-set="entries">\n                        <div t-if="0 &lt; sale_order.amount_paid &lt; sale_order.amount_total                                   and sale_order.state != 'cancel'" class="alert alert-success mt-3" role="alert">\n                            Amount paid:\n                            <span t-field="sale_order.amount_paid" t-options="{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id,                                 }"/>\n                        </div>\n\n                        <div class="d-flex flex-column gap-4 mt-3">\n                            <div class="d-flex flex-column gap-2" id="sale_order_sidebar_button">\n                                <a t-if="sale_order._has_to_be_signed() and not payment_amount" role="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#"> <!-- If paying by link, signing is skipped. -->\n                                    <i class="fa fa-check"/>\n                                    <t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t>\n                                    <t t-else=""> Accept &amp; Sign</t>\n                                </a>\n                                <a t-elif="sale_order._has_to_be_paid()                                             or (                                                 payment_amount                                                 and sale_order.amount_paid &lt; sale_order.amount_total                                                 and sale_order.state != 'cancel'                                             )" id="o_sale_portal_paynow" role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'btn btn-primary' if not sale_order.transaction_ids else 'btn btn-light'">\n                                    <i class="fa fa-check"/>\n                                    <t t-if="not sale_order.signature                                              and sale_order._has_to_be_paid()                                              and not payment_amount"> Accept &amp; Pay</t>\n                                    <t t-else=""> Pay Now</t>\n                                </a>\n                                <div id="print_invoice_sidebar_button" class="o_download_pdf d-flex gap-2 flex-lg-column flex-xl-row flex-wrap">\n                                    <a class="btn btn-light o_print_btn o_portal_invoice_print flex-grow-1" t-att-href="sale_order.get_portal_url(report_type='pdf')" id="print_invoice_report" title="View Details" role="button" target="_blank"><i class="fa fa-print me-1"/>View Details</a>\n                                </div>\n                            </div>\n\n                            <div class="navspy flex-grow-1 ps-0" t-ignore="true" role="complementary">\n                                <ul class="nav flex-column bs-sidenav"/>\n                            </div>\n\n                            <t t-if="not sale_order.is_expired and sale_order.state in ['draft', 'sent']">\n                                <div t-if="sale_order.amount_undiscounted - sale_order.amount_untaxed &gt; 0.01" class="list-group-item flex-grow-1" name="sale_order_advantage">\n                                    <small><b class="text-muted">Your advantage</b></small>\n                                    <small>\n                                        <b t-field="sale_order.amount_undiscounted" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}" style="text-decoration: line-through" class="d-block mt-1" data-id="amount_undiscounted"/>\n                                    </small>\n                                    <t t-if="sale_order.amount_untaxed == sale_order.amount_total">\n                                        <h4 t-field="sale_order.amount_total" class="text-success" data-id="total_amount"/>\n                                    </t>\n                                    <t t-else="">\n                                        <h4 t-field="sale_order.amount_untaxed" class="text-success mb-0" data-id="total_untaxed"/>\n                                        <small>(<span t-field="sale_order.amount_total" data-id="total_amount"/> Incl. tax)</small>\n                                    </t>\n                                </div>\n                            </t>\n\n                            <div t-if="sale_order.user_id">\n                                <h6><small class="text-muted">Your contact</small></h6>\n                                <t t-call="portal.portal_my_contact">\n                                    <t t-set="_contactAvatar" t-value="image_data_uri(sale_order.user_id.avatar_128)"/>\n                                    <t t-set="_contactName" t-value="sale_order.user_id.name"/>\n                                    <t t-set="_contactLink" t-value="True"/>\n                                </t>\n                            </div>\n\n                            <div t-if="sale_order._get_edi_builders()">\n                                <button id="portal_connect_software_modal_btn" type="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#sale_portal_connect_software_modal">\n                                        Connect with your software!\n                                </button>\n                            </div>\n                        </div>\n                    </t>\n                </t>\n\n                <div class="modal fade" id="sale_portal_connect_software_modal" tabindex="-1" role="dialog" aria-hidden="true">\n                    <div class="modal-dialog modal-lg" role="document">\n                        <div class="modal-content">\n                            <div class="modal-body">\n                                <div>\n                                    <h5>Want to import this document in Odoo?</h5>\n                                    <p>Drag and drop the request for quotation PDF file into your list of quotations in Odoo. Enjoy the automation!</p>\n                                </div>\n                                <div>\n                                    <h5>Not using Odoo?</h5>\n                                    <div class="input-group mb-3 w-50">\n                                        <t t-set="base_address" t-value="sale_order.env['ir.config_parameter'].sudo().get_param('web.base.url')"/>\n                                        <t t-set="doc_url" t-value="base_address + '/my/orders/' + str(sale_order.id) + '/download_edi?' + str(keep_query())"/>\n                                        <input type="text" class="form-control" aria-describedby="copy-button" readonly="readonly" t-att-value="doc_url"/>\n                                        <button class="btn btn-outline-secondary" type="button" id="copy-button" t-attf-onclick="navigator.clipboard.writeText('#{doc_url}')">Copy</button>\n                                    </div>\n                                    <p>Use the above REST URL to get structured data of the purchase order in UBL format.\n                                        <a href="https://www.odoo.com/documentation/">Read the documentation </a>to learn all the ways to connect your software with <a href="https://www.odoo.com">Odoo</a>.\n                                    </p>\n                                </div>\n                                <div>\n                                    <h5>You don't use a good CRM software?</h5>\n                                    <p><a href="https://www.odoo.com/app/sales">Start on Odoo</a>, it's 100% free! You'll save time creating beautiful quotations and track sales.</p>\n                                </div>\n                            </div>\n                            <div class="modal-footer justify-content-between">\n                                <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- Page content -->\n                <div id="quote_content" class="col-12 col-lg-8 col-xxl-9 mt-5 mt-lg-0">\n\n                    <!-- Modals container -->\n                    <div role="dialog" class="modal fade" id="modalaccept" name="sale_order_modal_sign_and_pay">\n                        <div t-if="sale_order._has_to_be_signed() and not payment_amount" class="modal-dialog"><t t-call="sale.sale_order_portal_sign_modal"/></div>\n                        <div t-elif="not sale_order._has_to_be_signed()                                     and sale_order._has_to_be_paid()                                     or (payment_amount and sale_order.state != 'cancel')" name="sale_order_modal_validate" class="modal-dialog"><t t-call="sale.sale_order_portal_pay_modal"/></div>\n                    </div>\n\n                    <!-- modal relative to the action reject -->\n                    <div role="dialog" class="modal fade" id="modaldecline">\n                        <div class="modal-dialog">\n                            <form id="decline" method="POST" t-attf-action="/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}" class="modal-content">\n                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n                                <header class="modal-header">\n                                    <h4 class="modal-title">Reject This Quotation</h4>\n                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n                                </header>\n                                <main class="modal-body">\n                                    <p>\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\n                                    </p>\n                                    <textarea rows="4" name="decline_message" required="" placeholder="Your feedback..." class="form-control"/>\n                                </main>\n                                <footer class="modal-footer">\n                                    <button type="submit" t-att-id="sale_order.id" class="btn btn-danger">\n                                        <i class="fa fa-times"/> Reject\n                                    </button>\n                                    <button type="button" class="btn btn-primary" data-bs-dismiss="modal">\n                                        Cancel\n                                    </button>\n                                </footer>\n                            </form>\n                        </div>\n                    </div>\n\n                    <!-- status messages -->\n                    <div t-if="message == 'sign_ok'" class="alert alert-success alert-dismissible d-print-none" role="status">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        <strong>Thank You!</strong><br/>\n                        <t t-if="message == 'sign_ok' and sale_order.state == 'sale'">\n                            Your order has been confirmed.\n                        </t>\n                        <t t-elif="message == 'sign_ok' and sale_order._has_to_be_paid()">\n                            Your order has been signed but still needs to be paid to be confirmed.\n                        </t>\n                        <t t-else="">Your order has been signed.</t>\n                    </div>\n\n                    <div t-if="message == 'cant_reject'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>\n                        Your order is not in a state to be rejected.\n                    </div>\n\n                    <t t-set="current_tx" t-value="sale_order.get_portal_last_transaction()"/>\n                    <!-- hide state header when invoice is posted for current transaction. -->\n                    <t t-if="current_tx and not (current_tx.state == 'done' and len(current_tx.invoice_ids) == 1 and current_tx.invoice_ids.state == 'posted')">\n                        <t t-call="payment.state_header">\n                            <t t-set="tx" t-value="current_tx"/>\n                        </t>\n                    </t>\n\n                    <div t-if="sale_order.state == 'cancel'" class="alert alert-danger alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This quotation has been cancelled.</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <div t-if="sale_order.is_expired" class="alert alert-warning alert-dismissible d-print-none" role="alert">\n                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>\n                        <strong>This offer expired!</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <!-- main content -->\n                    <div t-attf-class="#{'pb-5' if report_type == 'html' else ''}" id="portal_sale_content">\n                        <div><t t-call="#{sale_order._get_name_portal_content_view()}"/></div>\n                    </div>\n\n                    <!-- bottom actions -->\n                    <div t-if="sale_order._has_to_be_signed() or sale_order._has_to_be_paid()" class="d-flex justify-content-center gap-1 d-print-none" name="sale_order_actions">\n\n                        <t t-if="sale_order._has_to_be_signed()">\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#"><i class="fa fa-check"/><t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t><t t-else=""> Accept &amp; Sign</t></a>\n                            </div>\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-light" href="#discussion"><i class="fa fa-comment"/> Feedback</a>\n                            </div>\n                            <div class="col-sm-auto mt8">\n                                <a role="button" class="btn btn-danger" data-bs-toggle="modal" data-bs-target="#modaldecline" href="#"> <i class="fa fa-times"/> Reject</a>\n                            </div>\n                        </t>\n                        <div t-elif="sale_order._has_to_be_paid()" class="col-sm-auto mt8">\n                            <a role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="'%s' % ('btn btn-light' if sale_order.transaction_ids else 'btn btn-primary')">\n                                <i class="fa fa-check"/> <t t-if="not sale_order.signature">Accept &amp; Pay</t><t t-else="">Pay Now</t>\n                            </a>\n                        </div>\n                    </div>\n\n                    <!-- chatter -->\n                    <hr/>\n                    <div id="sale_order_communication">\n                        <h3>Communication history</h3>\n                        <t t-call="portal.message_thread"/>\n                    </div>\n                </div><!-- // #quote_content -->\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">sale.sale_order_portal_template</attribute></xpath></data>\n\n    	f	t	2026-05-21 05:55:17.744788	2026-05-21 05:55:17.744788	f
1278	16	\N	1	1	Sales Order Portal Sign Modal	\N	sale.sale_order_portal_sign_modal	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<t name=\\"Sales Order Portal Sign Modal\\" t-name=\\"sale.sale_order_portal_sign_modal\\">\\n        <form id=\\"accept\\" method=\\"POST\\" t-att-data-order-id=\\"sale_order.id\\" t-att-data-token=\\"sale_order.access_token\\" class=\\"js_accept_json modal-content js_website_submit_form\\">\\n            <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n            <header class=\\"modal-header\\">\\n                <h4 class=\\"modal-title\\">Validate Order</h4>\\n                <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Close\\"/>\\n            </header>\\n            <main class=\\"modal-body\\" id=\\"sign-dialog\\">\\n                <span>\\n                    By signing, you confirm acceptance on behalf of\\n                    <b t-field=\\"sale_order.partner_id.commercial_partner_id\\"/>\\n                    for the <b data-id=\\"total_amount\\" t-field=\\"sale_order.amount_total\\"/> quote.\\n                </span>\\n                <b t-if=\\"sale_order.payment_term_id\\" t-field=\\"sale_order.payment_term_id.note\\"/>\\n                <t t-call=\\"portal.signature_form\\">\\n                    <t t-set=\\"call_url\\" t-value=\\"sale_order.get_portal_url(suffix='/accept')\\"/>\\n                    <t t-set=\\"default_name\\" t-value=\\"sale_order.partner_id.name or sale_order.partner_id.commercial_partner_id.name\\"/>\\n                </t>\\n            </main>\\n        </form>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Sales Order Portal Sign Modal" t-name="sale.sale_order_portal_sign_modal">\n        <form id="accept" method="POST" t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="js_accept_json modal-content js_website_submit_form">\n            <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n            <header class="modal-header">\n                <h4 class="modal-title">Validate Order</h4>\n                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n            </header>\n            <main class="modal-body" id="sign-dialog">\n                <span>\n                    By signing, you confirm acceptance on behalf of\n                    <b t-field="sale_order.partner_id.commercial_partner_id"/>\n                    for the <b data-id="total_amount" t-field="sale_order.amount_total"/> quote.\n                </span>\n                <b t-if="sale_order.payment_term_id" t-field="sale_order.payment_term_id.note"/>\n                <t t-call="portal.signature_form">\n                    <t t-set="call_url" t-value="sale_order.get_portal_url(suffix='/accept')"/>\n                    <t t-set="default_name" t-value="sale_order.partner_id.name or sale_order.partner_id.commercial_partner_id.name"/>\n                </t>\n            </main>\n        </form>\n    </t>\n\n    	f	t	2026-05-21 05:55:17.744788	2026-05-21 05:55:17.744788	f
1279	16	\N	1	1	Sales Order Portal Pay Modal	\N	sale.sale_order_portal_pay_modal	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<t name=\\"Sales Order Portal Pay Modal\\" t-name=\\"sale.sale_order_portal_pay_modal\\">\\n        <div class=\\"modal-content\\">\\n            <header class=\\"modal-header\\">\\n                <h4 class=\\"modal-title\\">Pay Order</h4>\\n                <button type=\\"button\\" class=\\"btn-close\\" data-bs-dismiss=\\"modal\\" aria-label=\\"Close\\"/>\\n            </header>\\n            <main class=\\"modal-body\\" id=\\"sign-dialog\\">\\n                <t t-set=\\"prepayment_amount\\" t-value=\\"sale_order._get_prepayment_required_amount()\\"/>\\n                <t t-set=\\"prepayment_available\\" t-value=\\"sale_order.prepayment_percent                              and sale_order.prepayment_percent != 1.0\\"/>\\n                <t t-if=\\"sale_order._has_to_be_paid() and prepayment_available\\" t-call=\\"sale.sale_order_portal_pay_modal_amount_selector\\"/>\\n                <div t-if=\\"sale_order._has_to_be_paid()\\" class=\\"mb-3\\">\\n                    <!-- The widget associated with this modal will hide and show spans depending of the selected option. -->\\n                    <span t-if=\\"prepayment_available\\">\\n                        <span id=\\"o_sale_portal_use_amount_prepayment\\">\\n                            By paying a <u>down payment</u> of\\n                            <span t-out=\\"amount\\" t-options=\\"{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id                                 }\\" class=\\"fw-bold\\"/>\\n                            <t t-if=\\"sale_order._get_prepayment_required_amount() == amount\\">\\n                                (<b t-esc=\\"sale_order.prepayment_percent * 100\\"/>%),\\n                            </t>\\n                        </span>\\n                        <span id=\\"o_sale_portal_use_amount_total\\">By paying,</span>\\n                    </span>\\n                    <span t-else=\\"\\">\\n                        By paying,\\n                        <span t-out=\\"amount\\" t-options=\\"{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }\\" class=\\"fw-bold\\"/>\\n                    </span>\\n                    you confirm acceptance on behalf of\\n                    <b t-field=\\"sale_order.partner_id.commercial_partner_id\\"/>\\n                    for the <b data-id=\\"total_amount\\" t-field=\\"sale_order.amount_total\\"/> quote.\\n                    <b t-if=\\"sale_order.payment_term_id\\" t-field=\\"sale_order.payment_term_id.note\\" class=\\"o_sale_payment_terms\\"/>\\n                </div>\\n                <div t-if=\\"payment_amount and not sale_order._has_to_be_paid()\\" class=\\"mb-3\\">\\n                    Amount:\\n                    <span t-out=\\"payment_amount\\" t-options=\\"{                             'widget': 'monetary',                             'display_currency': sale_order.currency_id,                         }\\" class=\\"fw-bold\\"/>\\n                </div>\\n                <div t-if=\\"company_mismatch\\"><t t-call=\\"payment.company_mismatch_warning\\"/></div>\\n                <div t-elif=\\"not sale_order._has_to_be_paid() and not payment_amount\\" class=\\"alert alert-danger\\">\\n                    The order is not in a state requiring customer payment.\\n                </div>\\n                <div t-else=\\"\\" id=\\"payment_method\\" class=\\"text-start mt-0\\">\\n                    <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->\\n                    <t t-call=\\"payment.form\\" sale_order_id=\\"sale_order.id\\"/>\\n                </div>\\n            </main>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Sales Order Portal Pay Modal" t-name="sale.sale_order_portal_pay_modal">\n        <div class="modal-content">\n            <header class="modal-header">\n                <h4 class="modal-title">Pay Order</h4>\n                <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>\n            </header>\n            <main class="modal-body" id="sign-dialog">\n                <t t-set="prepayment_amount" t-value="sale_order._get_prepayment_required_amount()"/>\n                <t t-set="prepayment_available" t-value="sale_order.prepayment_percent                              and sale_order.prepayment_percent != 1.0"/>\n                <t t-if="sale_order._has_to_be_paid() and prepayment_available" t-call="sale.sale_order_portal_pay_modal_amount_selector"/>\n                <div t-if="sale_order._has_to_be_paid()" class="mb-3">\n                    <!-- The widget associated with this modal will hide and show spans depending of the selected option. -->\n                    <span t-if="prepayment_available">\n                        <span id="o_sale_portal_use_amount_prepayment">\n                            By paying a <u>down payment</u> of\n                            <span t-out="amount" t-options="{                                     'widget': 'monetary',                                     'display_currency': sale_order.currency_id                                 }" class="fw-bold"/>\n                            <t t-if="sale_order._get_prepayment_required_amount() == amount">\n                                (<b t-esc="sale_order.prepayment_percent * 100"/>%),\n                            </t>\n                        </span>\n                        <span id="o_sale_portal_use_amount_total">By paying,</span>\n                    </span>\n                    <span t-else="">\n                        By paying,\n                        <span t-out="amount" t-options="{                                 'widget': 'monetary',                                 'display_currency': sale_order.currency_id,                             }" class="fw-bold"/>\n                    </span>\n                    you confirm acceptance on behalf of\n                    <b t-field="sale_order.partner_id.commercial_partner_id"/>\n                    for the <b data-id="total_amount" t-field="sale_order.amount_total"/> quote.\n                    <b t-if="sale_order.payment_term_id" t-field="sale_order.payment_term_id.note" class="o_sale_payment_terms"/>\n                </div>\n                <div t-if="payment_amount and not sale_order._has_to_be_paid()" class="mb-3">\n                    Amount:\n                    <span t-out="payment_amount" t-options="{                             'widget': 'monetary',                             'display_currency': sale_order.currency_id,                         }" class="fw-bold"/>\n                </div>\n                <div t-if="company_mismatch"><t t-call="payment.company_mismatch_warning"/></div>\n                <div t-elif="not sale_order._has_to_be_paid() and not payment_amount" class="alert alert-danger">\n                    The order is not in a state requiring customer payment.\n                </div>\n                <div t-else="" id="payment_method" class="text-start mt-0">\n                    <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->\n                    <t t-call="payment.form" sale_order_id="sale_order.id"/>\n                </div>\n            </main>\n        </div>\n    </t>\n\n    	f	t	2026-05-21 05:55:17.744788	2026-05-21 05:55:17.744788	f
1280	16	\N	1	1	Sales Order Portal Pay Modal Amounts Selector	\N	sale.sale_order_portal_pay_modal_amount_selector	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<t name=\\"Sales Order Portal Pay Modal Amounts Selector\\" t-name=\\"sale.sale_order_portal_pay_modal_amount_selector\\">\\n        <div class=\\"d-flex btn-group mb-3\\" role=\\"group\\">\\n            <button name=\\"o_sale_portal_amount_prepayment_button\\" class=\\"btn btn-light active\\">\\n                Down payment <br/>\\n                <span t-if=\\"not payment_amount or payment_amount == sale_order.amount_total\\" t-out=\\"prepayment_amount\\" t-options=\\"{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }\\" class=\\"fw-bold\\"/>\\n                <span t-else=\\"\\" t-out=\\"payment_amount\\" t-options=\\"{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }\\" class=\\"fw-bold\\"/>\\n            </button>\\n            <button name=\\"o_sale_portal_amount_total_button\\" class=\\"btn btn-light\\">\\n                Full amount <br/>\\n                <span t-out=\\"sale_order.amount_total\\" t-options=\\"{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }\\" class=\\"fw-bold\\"/>\\n            </button>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Sales Order Portal Pay Modal Amounts Selector" t-name="sale.sale_order_portal_pay_modal_amount_selector">\n        <div class="d-flex btn-group mb-3" role="group">\n            <button name="o_sale_portal_amount_prepayment_button" class="btn btn-light active">\n                Down payment <br/>\n                <span t-if="not payment_amount or payment_amount == sale_order.amount_total" t-out="prepayment_amount" t-options="{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }" class="fw-bold"/>\n                <span t-else="" t-out="payment_amount" t-options="{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }" class="fw-bold"/>\n            </button>\n            <button name="o_sale_portal_amount_total_button" class="btn btn-light">\n                Full amount <br/>\n                <span t-out="sale_order.amount_total" t-options="{                         'widget': 'monetary',                         'display_currency': sale_order.currency_id,                     }" class="fw-bold"/>\n            </button>\n        </div>\n    </t>\n\n    	f	t	2026-05-21 05:55:17.744788	2026-05-21 05:55:17.744788	f
1281	16	\N	1	1	Sales Order Portal Content	\N	sale.sale_order_portal_content	qweb	sale/views/sale_portal_templates.xml	primary	{"en_US": "<t name=\\"Sales Order Portal Content\\" t-name=\\"sale.sale_order_portal_content\\">\\n        <!-- Intro -->\\n        <div id=\\"introduction\\" t-attf-class=\\"#{'border-bottom-0 pt-0 pb-3' if report_type == 'html' else ''}\\">\\n            <div class=\\"d-flex gap-2\\" id=\\"intro_row\\">\\n                <h2>\\n                    <t t-out=\\"sale_order.type_name\\"/> -\\n                    <em t-out=\\"sale_order.name\\"/>\\n                </h2>\\n            </div>\\n        </div>\\n        <div id=\\"content\\">\\n            <div id=\\"informations\\" class=\\"row\\">\\n                <span id=\\"transaction_info\\">\\n                    <div t-if=\\"sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error\\" t-att-data-order-id=\\"sale_order.id\\">\\n                        <t t-if=\\"sale_order.transaction_ids\\">\\n                            <t t-call=\\"payment.state_header\\">\\n                            <t t-set=\\"tx\\" t-value=\\"sale_order.get_portal_last_transaction()\\"/>\\n                        </t>\\n                    </t>\\n                    </div>\\n                </span>\\n                <!-- Information -->\\n                <div id=\\"sale_info\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <span id=\\"sale_info_title\\">\\n                        <h5 class=\\"mb-1\\">Sale Information</h5>\\n                        <hr class=\\"mt-1 mb-2\\"/>\\n                    </span>\\n                    <table class=\\"table table-borderless table-sm\\">\\n                        <tbody style=\\"white-space:nowrap\\" id=\\"sale_info_table\\">\\n                            <tr>\\n                                <th t-if=\\"sale_order.state in ['sale', 'cancel']\\" class=\\"ps-0 pb-0\\">Order Date:</th>\\n                                <th t-else=\\"\\" class=\\"ps-0 pb-0\\">Date:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></td>\\n                            </tr>\\n                            <tr t-if=\\"sale_order.validity_date and sale_order.state in ['draft', 'sent']\\">\\n                                <th class=\\"ps-0 pb-0\\">Expiration Date:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.validity_date\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/></td>\\n                            </tr>\\n                            <tr t-if=\\"sale_order.client_order_ref\\">\\n                                <th class=\\"ps-0 pb-0\\">Your Reference:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\"><span t-field=\\"sale_order.client_order_ref\\"/></td>\\n                            </tr>\\n                            <tr t-if=\\"sale_order.commitment_date\\">\\n                                <th class=\\"ps-0 pb-0\\">Delivery Date:</th>\\n                                <td class=\\"w-100 pb-0 text-wrap\\">\\n                                    <span t-field=\\"sale_order.commitment_date\\" t-options=\\"{'widget': 'date'}\\"/>\\n                                </td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <!-- ======  Customer Information  ====== -->\\n                <div id=\\"customer_info\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <h5 class=\\"mb-1\\">\\n                        <t t-if=\\"sale_order.partner_shipping_id == sale_order.partner_invoice_id\\">\\n                            Invoicing and Shipping Address\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            Invoicing Address\\n                        </t>\\n                        <small t-if=\\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\\">\\n                            <a class=\\"small\\" t-attf-href=\\"/my/account?redirect={{sale_order.get_portal_url()}}\\">\\n                                <i class=\\"fa fa-fw fa-pencil\\"/>\\n                            </a>\\n                        </small>\\n                    </h5>\\n                    <hr class=\\"mt-1 mb-2\\"/>\\n                    <div t-field=\\"sale_order.partner_invoice_id\\" t-options=\\"{'widget': 'contact', 'fields': ['name', 'address', 'phone', 'email']}\\"/>\\n                    <span t-if=\\"sale_order.partner_shipping_id != sale_order.partner_invoice_id\\" id=\\"shipping_address\\" class=\\"col-lg-6\\">\\n                        <br/>\\n                        <h5 class=\\"mb-1\\">\\n                            Shipping Address\\n                        </h5>\\n                        <hr class=\\"mt-1 mb-2\\"/>\\n                        <div t-field=\\"sale_order.partner_shipping_id\\" t-options=\\"{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}\\"/>\\n                    </span>\\n                </div>\\n                <t t-set=\\"invoices\\" t-value=\\"sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)[:3]\\"/>\\n                <div id=\\"sale_invoices\\" t-if=\\"invoices and sale_order.state in ['sale', 'cancel']\\" class=\\"col-12 col-lg-6 mb-4\\">\\n                    <h5 class=\\"mb-1\\">Last Invoices</h5>\\n                    <hr class=\\"mt-1 mb-2\\"/>\\n                    <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                        <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url()\\"/>\\n                        <t t-set=\\"authorized_tx_ids\\" t-value=\\"i.sudo().authorized_transaction_ids\\"/>\\n                        <div class=\\"d-flex flex-column gap-2\\">\\n                            <div class=\\"d-flex flex-column\\">\\n                                <div class=\\"d-flex align-items-center justify-content-between\\">\\n                                    <a t-att-href=\\"report_url\\">\\n                                        <span t-out=\\"i.name\\"/>\\n                                    </a>\\n                                    <div t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"small badge rounded-pill text-bg-success orders_label_text_align\\">\\n                                        <i class=\\"fa fa-fw fa-check\\"/> Paid\\n                                    </div>\\n                                    <div t-elif=\\"i.payment_state == 'reversed'\\" class=\\"small badge text-bg-success orders_label_text_align\\">\\n                                        <i class=\\"fa fa-fw fa-check\\"/> Reversed\\n                                    </div>\\n                                    <div t-elif=\\"authorized_tx_ids\\" class=\\"small badge rounded-pill text-bg-success orders_label_text_align\\">\\n                                        <i class=\\"fa fa-fw fa-check\\"/> Authorized\\n                                    </div>\\n                                    <div t-else=\\"\\" class=\\"small badge rounded-pill text-bg-info orders_label_text_align\\">\\n                                        <i class=\\"fa fa-fw fa-clock-o\\"/> Waiting Payment\\n                                    </div>\\n                                </div>\\n                                <div class=\\"small d-lg-inline-block\\">Date: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                            </div>\\n                        </div>\\n                    </t>\\n                </div>\\n            </div>\\n\\n            <section id=\\"details\\" style=\\"page-break-inside: auto;\\">\\n                <t t-if=\\"product_documents\\">\\n                    <h4 id=\\"details\\">Documents</h4>\\n                    <div class=\\"d-flex flex-grow-1 flex-wrap gap-1 mb32\\">\\n                        <t t-foreach=\\"product_documents\\" t-as=\\"document_sudo\\">\\n                            <div class=\\"bg-light p-2 rounded\\">\\n                                <div class=\\"position-relative text-center\\">\\n                                    <t t-set=\\"attachment_sudo\\" t-value=\\"document_sudo.ir_attachment_id\\"/>\\n                                    <t t-set=\\"target\\" t-value=\\"attachment_sudo.type == 'url' and '_blank' or '_self'\\"/>\\n                                    <a t-att-href=\\"sale_order.get_portal_url('/document/' + str(document_sudo.id))\\" t-att-target=\\"target\\" class=\\"d-flex flex-row\\">\\n                                        <div class=\\"o_image\\" t-att-title=\\"attachment_sudo.name\\" t-att-data-mimetype=\\"attachment_sudo.mimetype\\" t-attf-data-src=\\"/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}\\"/>\\n                                        <div class=\\"o_portal_product_document align-self-center\\" t-out=\\"attachment_sudo.name\\"/>\\n                                    </a>\\n                                </div>\\n                            </div>\\n                        </t>\\n                    </div>\\n                </t>\\n\\n                <t t-set=\\"lines_to_report\\" t-value=\\"sale_order._get_order_lines_to_report()\\"/>\\n                <t t-set=\\"display_discount\\" t-value=\\"any(line.discount &gt; 0 for line in lines_to_report)\\"/>\\n                <t t-set=\\"hide_taxes_details\\" t-value=\\"False\\"/>\\n                <t t-set=\\"display_taxes\\" t-value=\\"not hide_taxes_details and any(line._has_taxes() for line in lines_to_report)\\"/>\\n\\n                <div name=\\"sol_table\\" class=\\"table-responsive\\">\\n                    <table t-att-data-order-id=\\"sale_order.id\\" t-att-data-token=\\"sale_order.access_token\\" class=\\"table table-sm\\" id=\\"sales_order_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th class=\\"text-start\\" id=\\"product_name_header\\">Products</th>\\n                                <th class=\\"text-end\\" id=\\"product_qty_header\\">Quantity</th>\\n                                <th t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\" id=\\"product_unit_price_header\\">\\n                                    Unit Price\\n                                </th>\\n                                <th t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\" id=\\"product_discount_header\\">\\n                                    <span>Disc.%</span>\\n                                </th>\\n                                <th t-if=\\"display_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\" id=\\"taxes_header\\">\\n                                    <span>Taxes</span>\\n                                </th>\\n                                <th class=\\"text-end\\" id=\\"subtotal_header\\">\\n                                    <span>Amount</span>\\n                                </th>\\n                            </tr>\\n                        </thead>\\n                        <tbody class=\\"sale_tbody\\">\\n\\n                            <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"price_field\\" t-value=\\"'price_total' if hide_taxes_details else 'price_subtotal'\\"/>\\n\\n                            <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                                <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                                <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                                <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                                <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                                <t t-if=\\"is_section\\">\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"0\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-elif=\\"is_subsection\\">\\n                                    <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"line_padding\\" t-value=\\"2\\"/>\\n                                    <t t-set=\\"collapse_prices\\" t-value=\\"current_section.collapse_prices or line.collapse_prices\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"3 if current_subsection else (2 if current_section else 0)\\"/>\\n                                </t>\\n\\n                                <t t-if=\\"line.combo_item_id\\">\\n                                    <t t-set=\\"line_padding\\" t-value=\\"line_padding + 1\\"/>\\n                                </t>\\n\\n                                <t t-set=\\"padding_class\\" t-value=\\"line_padding and ('px-' + str(line_padding)) or ''\\"/>\\n\\n                                <t t-if=\\"not line.collapse_composition\\">\\n                                    <tr t-if=\\"is_section or is_subsection\\" name=\\"tr_section\\" t-att-class=\\"'fw-bolder o_line_section' if is_section else 'fw-bold o_line_subsection'\\">\\n                                        <t t-set=\\"show_section_total\\" t-value=\\"is_section or not line.parent_id.collapse_prices\\"/>\\n                                        <t t-set=\\"section_name_colspan\\" t-value=\\"3 + (1 if display_discount else 0) + (1 if display_taxes else 0)\\"/>\\n                                        <t t-if=\\"not show_section_total\\">\\n                                            <t t-set=\\"section_name_colspan\\" t-value=\\"99\\"/>\\n                                        </t>\\n                                        <td name=\\"td_section_name\\" t-att-colspan=\\"section_name_colspan\\" t-att-class=\\"padding_class\\">\\n                                            <span t-field=\\"line.name\\"/>\\n                                        </td>\\n                                        <td t-if=\\"show_section_total\\" name=\\"td_section_price\\" class=\\"text-end o_price_total\\">\\n                                            <span name=\\"price_subtotal_section\\" t-out=\\"line._get_section_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_note\\" name=\\"tr_note\\" class=\\"fst-italic o_line_note\\">\\n                                        <td name=\\"td_note_name\\" colspan=\\"99\\" t-att-class=\\"padding_class\\">\\n                                            <span t-field=\\"line.name\\"/>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-elif=\\"is_combo\\" name=\\"tr_combo\\" class=\\"fw-bold o_line_subsection\\">\\n                                        <td name=\\"td_combo_name\\" t-att-class=\\"padding_class\\">\\n                                            <span t-field=\\"line.name\\">Combo Product</span>\\n                                        </td>\\n                                        <td name=\\"td_combo_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_combo_priceunit\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\"/>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_combo_discount\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\"/>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_combo_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"/>\\n                                        <td name=\\"td_combo_subtotal\\" class=\\"text-end\\">\\n                                            <span t-if=\\"not collapse_prices\\" name=\\"price_subtotal_combo\\" t-out=\\"line._get_combo_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                27.00\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-else=\\"\\" name=\\"tr_product\\">\\n                                        <td name=\\"td_product_name\\" t-att-class=\\"padding_class\\">\\n                                            <span name=\\"span_product_name\\" t-field=\\"line.name\\"/>\\n                                        </td>\\n                                        <td name=\\"td_product_quantity\\" class=\\"text-end\\">\\n                                            <div id=\\"quote_qty\\">\\n                                                <span t-field=\\"line.product_uom_qty\\"/>\\n                                                <span t-field=\\"line.product_uom_id\\"/>\\n                                            </div>\\n                                        </td>\\n                                        <td name=\\"td_product_priceunit\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <div t-if=\\"line.discount &gt;= 0\\" t-field=\\"line.price_unit\\" t-att-style=\\"line.discount and 'text-decoration: line-through' or None\\" t-att-class=\\"(line.discount and 'text-danger' or '') + ' text-end'\\" t-options=\\"{'widget': 'monetary', 'display_currency': line.currency_id}\\"/>\\n                                                <div t-if=\\"line.discount\\">\\n                                                    <t t-out=\\"(1-line.discount / 100.0) * line.price_unit\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}\\"/>\\n                                                </div>\\n                                            </t>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_product_discount\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <!-- ! Always check collapse_prices separately; keep discount condition below for XPath -->\\n                                                <strong t-if=\\"line.discount &gt; 0\\" class=\\"text-info\\">\\n                                                    <t t-out=\\"((line.discount % 1) and '%s' or '%d') % line.discount\\"/>%\\n                                                </strong>\\n                                            </t>\\n                                        </td>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_product_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                            <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                        </td>\\n                                        <td t-if=\\"not line.is_downpayment\\" name=\\"td_product_subtotal\\" class=\\"text-end\\">\\n                                            <t t-if=\\"not collapse_prices\\">\\n                                                <span t-if=\\"price_field == 'price_subtotal'\\" t-field=\\"line.price_subtotal\\"/>\\n                                                <span t-else=\\"\\" t-field=\\"line.price_total\\"/>\\n                                            </t>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <!-- Displaying the section inner content, grouped by taxes -->\\n                                    <tr t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\" name=\\"tr_section_group\\" class=\\"o_line_section\\">\\n                                        <td name=\\"td_section_group_name\\" t-att-class=\\"padding_class\\">\\n                                            <span t-field=\\"line.name\\">\\n                                                Section Summary\\n                                            </span>\\n                                        </td>\\n                                        <td name=\\"td_section_group_quantity\\" class=\\"text-end text-nowrap\\">\\n                                            <span>1.00 Units</span>\\n                                        </td>\\n                                        <td name=\\"td_section_group_priceunit\\" class=\\"text-end text-nowrap\\">\\n                                            <span t-out=\\"section_line['price_subtotal']\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\"/>\\n                                        </td>\\n                                        <td t-if=\\"display_discount\\" name=\\"td_section_group_discount\\"/>\\n                                        <td t-if=\\"display_taxes\\" name=\\"td_section_group_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(section_line['tax_labels']) &lt; 10 else '' }}\\">\\n                                            <span t-out=\\"', '.join(section_line['tax_labels'])\\">\\n                                                Tax 15%\\n                                            </span>\\n                                        </td>\\n                                        <td name=\\"td_section_group_total\\" class=\\"text-end o_price_total\\">\\n                                            <span name=\\"price_subtotal_section_grouped\\" t-out=\\"section_line[price_field]\\" t-options=\\"{'widget': 'monetary', 'display_currency': sale_order.currency_id}\\">\\n                                                31.05\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                </div>\\n\\n                <div id=\\"total\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                    <div class=\\"col-xs-7 col-md-5 ms-auto\\">\\n                        <t t-call=\\"sale.sale_order_portal_content_totals_table\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <section t-if=\\"sale_order.signature\\" id=\\"signature\\" name=\\"Signature\\">\\n                <div class=\\"row mt-4\\" name=\\"signature\\">\\n                    <div t-attf-class=\\"#{'col-3' if report_type != 'html' else 'col-sm-7 col-md-4'} ms-auto text-center\\">\\n                        <h5>Signature</h5>\\n                        <img t-att-src=\\"image_data_uri(sale_order.signature)\\" style=\\"max-height: 6rem; max-width: 100%;\\"/>\\n                        <p t-field=\\"sale_order.signed_by\\"/>\\n                    </div>\\n                </div>\\n            </section>\\n\\n            <section t-if=\\"not is_html_empty(sale_order.note)\\" id=\\"terms\\" class=\\"mt-4\\">\\n                <h4 class=\\"\\">Terms &amp; Conditions</h4>\\n                <hr class=\\"mt-0 mb-1\\"/>\\n                <em t-field=\\"sale_order.note\\"/>\\n            </section>\\n\\n            <section t-if=\\"sale_order.payment_term_id\\" class=\\"mt-4\\">\\n                <h4 class=\\"\\">Payment terms</h4>\\n                <hr class=\\"mt-0 mb-1\\"/>\\n                <span t-field=\\"sale_order.payment_term_id.note\\"/>\\n            </section>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Sales Order Portal Content" t-name="sale.sale_order_portal_content">\n        <!-- Intro -->\n        <div id="introduction" t-attf-class="#{'border-bottom-0 pt-0 pb-3' if report_type == 'html' else ''}">\n            <div class="d-flex gap-2" id="intro_row">\n                <h2>\n                    <t t-out="sale_order.type_name"/> -\n                    <em t-out="sale_order.name"/>\n                </h2>\n            </div>\n        </div>\n        <div id="content">\n            <div id="informations" class="row">\n                <span id="transaction_info">\n                    <div t-if="sale_order.get_portal_last_transaction() and not invoices and sale_order.state in ('sent', 'sale') and portal_confirmation == 'pay' and not success and not error" t-att-data-order-id="sale_order.id">\n                        <t t-if="sale_order.transaction_ids">\n                            <t t-call="payment.state_header">\n                            <t t-set="tx" t-value="sale_order.get_portal_last_transaction()"/>\n                        </t>\n                    </t>\n                    </div>\n                </span>\n                <!-- Information -->\n                <div id="sale_info" class="col-12 col-lg-6 mb-4">\n                    <span id="sale_info_title">\n                        <h5 class="mb-1">Sale Information</h5>\n                        <hr class="mt-1 mb-2"/>\n                    </span>\n                    <table class="table table-borderless table-sm">\n                        <tbody style="white-space:nowrap" id="sale_info_table">\n                            <tr>\n                                <th t-if="sale_order.state in ['sale', 'cancel']" class="ps-0 pb-0">Order Date:</th>\n                                <th t-else="" class="ps-0 pb-0">Date:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>\n                            </tr>\n                            <tr t-if="sale_order.validity_date and sale_order.state in ['draft', 'sent']">\n                                <th class="ps-0 pb-0">Expiration Date:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.validity_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>\n                            </tr>\n                            <tr t-if="sale_order.client_order_ref">\n                                <th class="ps-0 pb-0">Your Reference:</th>\n                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.client_order_ref"/></td>\n                            </tr>\n                            <tr t-if="sale_order.commitment_date">\n                                <th class="ps-0 pb-0">Delivery Date:</th>\n                                <td class="w-100 pb-0 text-wrap">\n                                    <span t-field="sale_order.commitment_date" t-options="{'widget': 'date'}"/>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- ======  Customer Information  ====== -->\n                <div id="customer_info" class="col-12 col-lg-6 mb-4">\n                    <h5 class="mb-1">\n                        <t t-if="sale_order.partner_shipping_id == sale_order.partner_invoice_id">\n                            Invoicing and Shipping Address\n                        </t>\n                        <t t-else="">\n                            Invoicing Address\n                        </t>\n                        <small t-if="sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id">\n                            <a class="small" t-attf-href="/my/account?redirect={{sale_order.get_portal_url()}}">\n                                <i class="fa fa-fw fa-pencil"/>\n                            </a>\n                        </small>\n                    </h5>\n                    <hr class="mt-1 mb-2"/>\n                    <div t-field="sale_order.partner_invoice_id" t-options="{'widget': 'contact', 'fields': ['name', 'address', 'phone', 'email']}"/>\n                    <span t-if="sale_order.partner_shipping_id != sale_order.partner_invoice_id" id="shipping_address" class="col-lg-6">\n                        <br/>\n                        <h5 class="mb-1">\n                            Shipping Address\n                        </h5>\n                        <hr class="mt-1 mb-2"/>\n                        <div t-field="sale_order.partner_shipping_id" t-options="{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}"/>\n                    </span>\n                </div>\n                <t t-set="invoices" t-value="sale_order.invoice_ids.filtered(lambda i: i.state not in ['draft', 'cancel']).sorted('date', reverse=True)[:3]"/>\n                <div id="sale_invoices" t-if="invoices and sale_order.state in ['sale', 'cancel']" class="col-12 col-lg-6 mb-4">\n                    <h5 class="mb-1">Last Invoices</h5>\n                    <hr class="mt-1 mb-2"/>\n                    <t t-foreach="invoices" t-as="i">\n                        <t t-set="report_url" t-value="i.get_portal_url()"/>\n                        <t t-set="authorized_tx_ids" t-value="i.sudo().authorized_transaction_ids"/>\n                        <div class="d-flex flex-column gap-2">\n                            <div class="d-flex flex-column">\n                                <div class="d-flex align-items-center justify-content-between">\n                                    <a t-att-href="report_url">\n                                        <span t-out="i.name"/>\n                                    </a>\n                                    <div t-if="i.payment_state in ('paid', 'in_payment')" class="small badge rounded-pill text-bg-success orders_label_text_align">\n                                        <i class="fa fa-fw fa-check"/> Paid\n                                    </div>\n                                    <div t-elif="i.payment_state == 'reversed'" class="small badge text-bg-success orders_label_text_align">\n                                        <i class="fa fa-fw fa-check"/> Reversed\n                                    </div>\n                                    <div t-elif="authorized_tx_ids" class="small badge rounded-pill text-bg-success orders_label_text_align">\n                                        <i class="fa fa-fw fa-check"/> Authorized\n                                    </div>\n                                    <div t-else="" class="small badge rounded-pill text-bg-info orders_label_text_align">\n                                        <i class="fa fa-fw fa-clock-o"/> Waiting Payment\n                                    </div>\n                                </div>\n                                <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n\n            <section id="details" style="page-break-inside: auto;">\n                <t t-if="product_documents">\n                    <h4 id="details">Documents</h4>\n                    <div class="d-flex flex-grow-1 flex-wrap gap-1 mb32">\n                        <t t-foreach="product_documents" t-as="document_sudo">\n                            <div class="bg-light p-2 rounded">\n                                <div class="position-relative text-center">\n                                    <t t-set="attachment_sudo" t-value="document_sudo.ir_attachment_id"/>\n                                    <t t-set="target" t-value="attachment_sudo.type == 'url' and '_blank' or '_self'"/>\n                                    <a t-att-href="sale_order.get_portal_url('/document/' + str(document_sudo.id))" t-att-target="target" class="d-flex flex-row">\n                                        <div class="o_image" t-att-title="attachment_sudo.name" t-att-data-mimetype="attachment_sudo.mimetype" t-attf-data-src="/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}"/>\n                                        <div class="o_portal_product_document align-self-center" t-out="attachment_sudo.name"/>\n                                    </a>\n                                </div>\n                            </div>\n                        </t>\n                    </div>\n                </t>\n\n                <t t-set="lines_to_report" t-value="sale_order._get_order_lines_to_report()"/>\n                <t t-set="display_discount" t-value="any(line.discount &gt; 0 for line in lines_to_report)"/>\n                <t t-set="hide_taxes_details" t-value="False"/>\n                <t t-set="display_taxes" t-value="not hide_taxes_details and any(line._has_taxes() for line in lines_to_report)"/>\n\n                <div name="sol_table" class="table-responsive">\n                    <table t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="table table-sm" id="sales_order_table">\n                        <thead>\n                            <tr>\n                                <th class="text-start" id="product_name_header">Products</th>\n                                <th class="text-end" id="product_qty_header">Quantity</th>\n                                <th t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}" id="product_unit_price_header">\n                                    Unit Price\n                                </th>\n                                <th t-if="display_discount" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}" id="product_discount_header">\n                                    <span>Disc.%</span>\n                                </th>\n                                <th t-if="display_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}" id="taxes_header">\n                                    <span>Taxes</span>\n                                </th>\n                                <th class="text-end" id="subtotal_header">\n                                    <span>Amount</span>\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody class="sale_tbody">\n\n                            <t t-set="current_section" t-value="None"/>\n                            <t t-set="current_subsection" t-value="None"/>\n                            <t t-set="price_field" t-value="'price_total' if hide_taxes_details else 'price_subtotal'"/>\n\n                            <t t-foreach="lines_to_report" t-as="line">\n\n                                <t t-set="is_note" t-value="line.display_type == 'line_note'"/>\n                                <t t-set="is_section" t-value="line.display_type == 'line_section'"/>\n                                <t t-set="is_subsection" t-value="line.display_type == 'line_subsection'"/>\n                                <t t-set="is_combo" t-value="line.product_type == 'combo'"/>\n\n                                <t t-if="is_section">\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subsection" t-value="None"/>\n                                    <t t-set="line_padding" t-value="0"/>\n                                    <t t-set="collapse_prices" t-value="line.collapse_prices"/>\n                                </t>\n                                <t t-elif="is_subsection">\n                                    <t t-set="current_subsection" t-value="line"/>\n                                    <t t-set="line_padding" t-value="2"/>\n                                    <t t-set="collapse_prices" t-value="current_section.collapse_prices or line.collapse_prices"/>\n                                </t>\n                                <t t-else="">\n                                    <t t-set="line_padding" t-value="3 if current_subsection else (2 if current_section else 0)"/>\n                                </t>\n\n                                <t t-if="line.combo_item_id">\n                                    <t t-set="line_padding" t-value="line_padding + 1"/>\n                                </t>\n\n                                <t t-set="padding_class" t-value="line_padding and ('px-' + str(line_padding)) or ''"/>\n\n                                <t t-if="not line.collapse_composition">\n                                    <tr t-if="is_section or is_subsection" name="tr_section" t-att-class="'fw-bolder o_line_section' if is_section else 'fw-bold o_line_subsection'">\n                                        <t t-set="show_section_total" t-value="is_section or not line.parent_id.collapse_prices"/>\n                                        <t t-set="section_name_colspan" t-value="3 + (1 if display_discount else 0) + (1 if display_taxes else 0)"/>\n                                        <t t-if="not show_section_total">\n                                            <t t-set="section_name_colspan" t-value="99"/>\n                                        </t>\n                                        <td name="td_section_name" t-att-colspan="section_name_colspan" t-att-class="padding_class">\n                                            <span t-field="line.name"/>\n                                        </td>\n                                        <td t-if="show_section_total" name="td_section_price" class="text-end o_price_total">\n                                            <span name="price_subtotal_section" t-out="line._get_section_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </td>\n                                    </tr>\n                                    <tr t-elif="is_note" name="tr_note" class="fst-italic o_line_note">\n                                        <td name="td_note_name" colspan="99" t-att-class="padding_class">\n                                            <span t-field="line.name"/>\n                                        </td>\n                                    </tr>\n                                    <tr t-elif="is_combo" name="tr_combo" class="fw-bold o_line_subsection">\n                                        <td name="td_combo_name" t-att-class="padding_class">\n                                            <span t-field="line.name">Combo Product</span>\n                                        </td>\n                                        <td name="td_combo_quantity" class="text-end">\n                                            <div id="quote_qty">\n                                                <span t-field="line.product_uom_qty"/>\n                                                <span t-field="line.product_uom_id"/>\n                                            </div>\n                                        </td>\n                                        <td name="td_combo_priceunit" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}"/>\n                                        <td t-if="display_discount" name="td_combo_discount" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}"/>\n                                        <td t-if="display_taxes" name="td_combo_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"/>\n                                        <td name="td_combo_subtotal" class="text-end">\n                                            <span t-if="not collapse_prices" name="price_subtotal_combo" t-out="line._get_combo_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}">\n                                                27.00\n                                            </span>\n                                        </td>\n                                    </tr>\n                                    <tr t-else="" name="tr_product">\n                                        <td name="td_product_name" t-att-class="padding_class">\n                                            <span name="span_product_name" t-field="line.name"/>\n                                        </td>\n                                        <td name="td_product_quantity" class="text-end">\n                                            <div id="quote_qty">\n                                                <span t-field="line.product_uom_qty"/>\n                                                <span t-field="line.product_uom_id"/>\n                                            </div>\n                                        </td>\n                                        <td name="td_product_priceunit" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                            <t t-if="not collapse_prices">\n                                                <div t-if="line.discount &gt;= 0" t-field="line.price_unit" t-att-style="line.discount and 'text-decoration: line-through' or None" t-att-class="(line.discount and 'text-danger' or '') + ' text-end'" t-options="{'widget': 'monetary', 'display_currency': line.currency_id}"/>\n                                                <div t-if="line.discount">\n                                                    <t t-out="(1-line.discount / 100.0) * line.price_unit" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}"/>\n                                                </div>\n                                            </t>\n                                        </td>\n                                        <td t-if="display_discount" name="td_product_discount" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                            <t t-if="not collapse_prices">\n                                                <!-- ! Always check collapse_prices separately; keep discount condition below for XPath -->\n                                                <strong t-if="line.discount &gt; 0" class="text-info">\n                                                    <t t-out="((line.discount % 1) and '%s' or '%d') % line.discount"/>%\n                                                </strong>\n                                            </t>\n                                        </td>\n                                        <td t-if="display_taxes" name="td_product_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                            <span t-out="', '.join(map(lambda x: (x.name), line.tax_ids))"/>\n                                        </td>\n                                        <td t-if="not line.is_downpayment" name="td_product_subtotal" class="text-end">\n                                            <t t-if="not collapse_prices">\n                                                <span t-if="price_field == 'price_subtotal'" t-field="line.price_subtotal"/>\n                                                <span t-else="" t-field="line.price_total"/>\n                                            </t>\n                                        </td>\n                                    </tr>\n                                </t>\n                                <t t-else="">\n                                    <!-- Displaying the section inner content, grouped by taxes -->\n                                    <tr t-foreach="line._get_grouped_section_summary(display_taxes)" t-as="section_line" name="tr_section_group" class="o_line_section">\n                                        <td name="td_section_group_name" t-att-class="padding_class">\n                                            <span t-field="line.name">\n                                                Section Summary\n                                            </span>\n                                        </td>\n                                        <td name="td_section_group_quantity" class="text-end text-nowrap">\n                                            <span>1.00 Units</span>\n                                        </td>\n                                        <td name="td_section_group_priceunit" class="text-end text-nowrap">\n                                            <span t-out="section_line['price_subtotal']" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}"/>\n                                        </td>\n                                        <td t-if="display_discount" name="td_section_group_discount"/>\n                                        <td t-if="display_taxes" name="td_section_group_taxes" t-attf-class="text-end {{ 'text-nowrap' if len(section_line['tax_labels']) &lt; 10 else '' }}">\n                                            <span t-out="', '.join(section_line['tax_labels'])">\n                                                Tax 15%\n                                            </span>\n                                        </td>\n                                        <td name="td_section_group_total" class="text-end o_price_total">\n                                            <span name="price_subtotal_section_grouped" t-out="section_line[price_field]" t-options="{'widget': 'monetary', 'display_currency': sale_order.currency_id}">\n                                                31.05\n                                            </span>\n                                        </td>\n                                    </tr>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n\n                <div id="total" name="total" style="page-break-inside: avoid;">\n                    <div class="col-xs-7 col-md-5 ms-auto">\n                        <t t-call="sale.sale_order_portal_content_totals_table"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if="sale_order.signature" id="signature" name="Signature">\n                <div class="row mt-4" name="signature">\n                    <div t-attf-class="#{'col-3' if report_type != 'html' else 'col-sm-7 col-md-4'} ms-auto text-center">\n                        <h5>Signature</h5>\n                        <img t-att-src="image_data_uri(sale_order.signature)" style="max-height: 6rem; max-width: 100%;"/>\n                        <p t-field="sale_order.signed_by"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if="not is_html_empty(sale_order.note)" id="terms" class="mt-4">\n                <h4 class="">Terms &amp; Conditions</h4>\n                <hr class="mt-0 mb-1"/>\n                <em t-field="sale_order.note"/>\n            </section>\n\n            <section t-if="sale_order.payment_term_id" class="mt-4">\n                <h4 class="">Payment terms</h4>\n                <hr class="mt-0 mb-1"/>\n                <span t-field="sale_order.payment_term_id.note"/>\n            </section>\n        </div>\n    </t>\n\n    	f	t	2026-05-21 05:55:17.744788	2026-05-21 05:55:17.744788	f
