1445	16	\N	1	1	tenancy_contract_page	\N	bliss_property_management.tenancy_contract_page	qweb	bliss_property_management/report/tenancy_contract_report_template.xml	primary	{"en_US": "<t t-name=\\"bliss_property_management.tenancy_contract_page\\">\\n        <t t-set=\\"company\\" t-value=\\"doc.company_id\\"/>\\n        <t t-set=\\"company_partner\\" t-value=\\"company.partner_id\\"/>\\n        <t t-set=\\"tenant\\" t-value=\\"doc.partner_id\\"/>\\n        <t t-set=\\"unit\\" t-value=\\"doc.unit_id\\"/>\\n        <t t-set=\\"installment_cheques\\" t-value=\\"doc._get_rent_installment_cheques().sorted(key=lambda c: (c.cheque_date or False, c.id))\\"/>\\n        <t t-set=\\"office_commission\\" t-value=\\"doc.commission_value and (doc.value * doc.commission_value / 100.0) or 0.0\\"/>\\n        <t t-set=\\"account_total\\" t-value=\\"(doc.value or 0.0) + office_commission\\"/>\\n        <t t-set=\\"contract_status\\" t-value=\\"'Renew' if doc.is_renew else ('New' if doc.state == 'signed' else doc.state)\\"/>\\n        <t t-set=\\"contract_type\\" t-value=\\"'Renew' if doc.is_renew else 'New'\\"/>\\n        <t t-set=\\"report_date\\" t-value=\\"doc.date or doc.date_start\\"/>\\n        <t t-set=\\"tenant_phone\\" t-value=\\"tenant.phone\\"/>\\n        <t t-set=\\"broker_name\\" t-value=\\"doc.user_id.name if doc.user_id else False\\"/>\\n\\n        <div class=\\"page tenancy-contract-page\\" style=\\"font-family: Arial, sans-serif; font-size: 11px; color: #000;\\">\\n            <table style=\\"width: 100%; border-collapse: collapse; margin-bottom: 10px;\\">\\n                <tr>\\n                    <td style=\\"width: 22%; vertical-align: top;\\"/>\\n                    <td style=\\"width: 56%; vertical-align: top; text-align: center; padding: 0 8px;\\">\\n                        <div style=\\"font-size: 17px; font-weight: bold; line-height: 1.35; margin-bottom: 4px;\\" t-esc=\\"company.name or ''\\"/>\\n                        <div style=\\"font-size: 12px; line-height: 1.4;\\" t-if=\\"company_partner.street\\" t-esc=\\"company_partner.street\\"/>\\n                        <div style=\\"font-size: 12px; line-height: 1.4;\\">\\n                            <t t-if=\\"company_partner.city\\" t-esc=\\"company_partner.city\\"/>\\n                            <t t-if=\\"company_partner.country_id\\">, <t t-esc=\\"company_partner.country_id.name\\"/></t>\\n                        </div>\\n                        <div style=\\"font-size: 12px; line-height: 1.4; margin-top: 2px;\\">\\n                            <t t-if=\\"company.phone\\">Tel: <t t-esc=\\"company.phone\\"/></t>\\n                            <t t-if=\\"company.phone\\"> , </t>\\n                            Fax: <t t-esc=\\"company.company_registry or ''\\"/>\\n                        </div>\\n                    </td>\\n                    <td style=\\"width: 22%; vertical-align: top; text-align: right; font-size: 13px; line-height: 1.6; padding-top: 2px;\\">\\n                        <div style=\\"font-size: 13px; margin-bottom: 3px;\\">\\n                            <span style=\\"font-weight: bold;\\">Status :</span>\\n                            <t t-esc=\\"contract_status\\"/>\\n                        </div>\\n                        <div style=\\"font-size: 13px; margin-bottom: 3px;\\">\\n                            <span style=\\"font-weight: bold;\\">Doc No :</span>\\n                            <t t-esc=\\"doc.code or 'code'\\"/>\\n                        </div>\\n                        <div style=\\"font-size: 13px;\\">\\n                            <span style=\\"font-weight: bold;\\">Date :</span>\\n                            <t t-if=\\"report_date\\" t-esc=\\"report_date\\" t-options=\\"{'widget': 'date'}\\"/>\\n                            <t t-else=\\"\\">date</t>\\n                        </div>\\n                    </td>\\n                </tr>\\n            </table>\\n\\n            <div style=\\"text-align: center; font-size: 18px; font-weight: bold; text-decoration: underline; margin: 12px 0 14px 0;\\">\\n                TENANCY CONTRACT\\n            </div>\\n\\n            <table style=\\"width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 10px;\\">\\n                <tr>\\n                    <td colspan=\\"6\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Tower Name :\\n                        <t t-esc=\\"doc.building_id.building_name if doc.building_id else ''\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Unit No :\\n                        <t t-esc=\\"unit.unit_no if unit and unit.unit_no else ''\\"/>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Unit Type :\\n                        <t t-esc=\\"unit.unit_type_id.name if unit and unit.unit_type_id else ''\\"/>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Floor :\\n                        <t t-esc=\\"unit.floor_no if unit and unit.floor_no else ''\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"6\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Tanent Name :\\n                        <t t-esc=\\"tenant.name if tenant else ''\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"6\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Chq. Payee Name :\\n                        <t t-esc=\\"tenant.name if tenant else ''\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"3\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Phone No :\\n                        <t t-esc=\\"tenant_phone if tenant_phone else ''\\"/>\\n                    </td>\\n                    <td colspan=\\"3\\" rowspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px; text-align: center; vertical-align: middle;\\">\\n                        <div>Length of Tenancy</div>\\n                        <div style=\\"margin-top: 8px;\\">\\n                            <t t-if=\\"doc.no_of_days\\" t-esc=\\"str(doc.no_of_days) + ' days'\\"/>\\n                            <t t-else=\\"\\">length_of_tenancy</t>\\n                        </div>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"3\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        EID :\\n                        <t t-esc=\\"tenant.emirateId_number if tenant and tenant.emirateId_number else ''\\"/>\\n                        <span style=\\"margin-left: 20px;\\">Nationality :\\n                            <t t-esc=\\"tenant.nationality.name if tenant and tenant.nationality else ''\\"/>\\n                        </span>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Contract Type <t t-esc=\\"contract_type\\"/>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Contract Start Date\\n                        <t t-if=\\"doc.date_start\\" t-esc=\\"doc.date_start\\" t-options=\\"{'widget': 'date'}\\"/>\\n                        <t t-else=\\"\\">date_start</t>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        End Date\\n                        <t t-if=\\"doc.date_stop\\" t-esc=\\"doc.date_stop\\" t-options=\\"{'widget': 'date'}\\"/>\\n                        <t t-else=\\"\\">date_stop</t>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Original Amount :\\n                        <t t-esc=\\"doc.format_report_currency(doc.value)\\"/>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Discount :\\n                        <t t-esc=\\"doc.discount or 0.0\\"/>\\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Net Amount :\\n                        <t t-esc=\\"doc.format_report_currency(doc.total_value)\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"3\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Previous Rent : \\n                    </td>\\n                    <td colspan=\\"3\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Base Rent :\\n                        <t t-esc=\\"doc.format_report_currency(doc.value)\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Living Purpose: \\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Adv. Source: \\n                    </td>\\n                    <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Broker:\\n                        <t t-esc=\\"broker_name if broker_name else ''\\"/>\\n                    </td>\\n                </tr>\\n                <tr>\\n                    <td colspan=\\"6\\" style=\\"border: 1px solid #000; padding: 4px 6px;\\">\\n                        Notes:\\n                        <t t-esc=\\"doc.notes if doc.notes else ''\\"/>\\n                    </td>\\n                </tr>\\n            </table>\\n\\n            <div style=\\"font-weight: bold; margin: 6px 0 4px 0;\\">Account Details</div>\\n            <table style=\\"width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 10px;\\">\\n                <thead>\\n                    <tr style=\\"background-color: #f2f2f2;\\">\\n                        <th style=\\"border: 1px solid #000; padding: 4px; width: 8%;\\">S No</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px; width: 62%;\\">Particulars</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px; width: 30%; text-align: right;\\">Amount</th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <tr>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: center;\\">1</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">Rent</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">\\n                            <t t-esc=\\"doc.format_report_currency(doc.value)\\"/>\\n                        </td>\\n                    </tr>\\n                    <tr>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: center;\\">2</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">Ejari Fees</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">\\n                        \\n                            <t t-esc=\\"doc.format_report_currency(doc.ejari_fees)\\"/>\\n                        \\n                        \\n                        </td>\\n                    </tr>\\n                    <tr>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: center;\\">3</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">Office Commission</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">\\n                                <t t-if=\\"doc.commission_value\\" t-esc=\\"doc.format_report_currency(office_commission)\\"/>\\n                            <t t-else=\\"\\"/>\\n                        </td>\\n                    </tr>\\n                    <tr>\\n                        <td colspan=\\"2\\" style=\\"border: 1px solid #000; padding: 4px; font-weight: bold;\\">TOTAL</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;\\">\\n                            <t t-esc=\\"doc.format_report_currency(account_total)\\"/>\\n                        </td>\\n                    </tr>\\n                </tbody>\\n            </table>\\n\\n            <div style=\\"font-weight: bold; margin: 6px 0 4px 0;\\">Payment Details</div>\\n            <table style=\\"width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 10px;\\">\\n                <thead>\\n                    <tr style=\\"background-color: #f2f2f2;\\">\\n                        <th style=\\"border: 1px solid #000; padding: 4px;\\">S No</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px;\\">DocID</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px;\\">ChequeNO</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px;\\">Che Date</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px;\\">PayeeBank</th>\\n                        <th style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">Amount</th>\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    <t t-foreach=\\"installment_cheques\\" t-as=\\"cheque\\">\\n                        <tr>\\n                            <td style=\\"border: 1px solid #000; padding: 4px; text-align: center;\\" t-esc=\\"cheque_index + 1\\"/>\\n                            <td style=\\"border: 1px solid #000; padding: 4px;\\" t-esc=\\"cheque.sequence or cheque.id\\"/>\\n                            <td style=\\"border: 1px solid #000; padding: 4px;\\" t-esc=\\"cheque.cheque_number\\"/>\\n                            <td style=\\"border: 1px solid #000; padding: 4px;\\">\\n                                <t t-if=\\"cheque.cheque_date\\" t-esc=\\"cheque.cheque_date\\" t-options=\\"{'widget': 'date'}\\"/>\\n                            </td>\\n                            <td style=\\"border: 1px solid #000; padding: 4px;\\">\\n                                <t t-esc=\\"doc.bank_id.name if doc.bank_id else ''\\"/>\\n                            </td>\\n                            <td style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">\\n                                <t t-esc=\\"doc.format_report_currency(cheque.display_total_amount)\\"/>\\n                            </td>\\n                        </tr>\\n                    </t>\\n                    <tr t-if=\\"not installment_cheques\\">\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: center;\\">1</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">doc_id</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">cheque_number</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">cheque_date</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px;\\">payee_bank</td>\\n                        <td style=\\"border: 1px solid #000; padding: 4px; text-align: right;\\">amount</td>\\n                    </tr>\\n                </tbody>\\n            </table>\\n\\n            <table style=\\"width: 100%; border-collapse: collapse; margin-top: 8px;\\">\\n                <tr>\\n                    <td style=\\"width: 75%; vertical-align: top; padding: 4px 0;\\">\\n                        Amount In Words:\\n                        <t t-if=\\"doc.contract_currency_id and doc.total_value\\">\\n                            <t t-esc=\\"doc.contract_currency_id.amount_to_text(doc.total_value)\\"/>\\n                        </t>\\n                        <t t-else=\\"\\">amount_in_words</t>\\n                    </td>\\n                    <td style=\\"width: 25%; text-align: right; font-weight: bold; vertical-align: top; padding: 4px 0;\\">\\n                        <t t-esc=\\"doc.format_report_currency(doc.total_value)\\"/>\\n                    </td>\\n                </tr>\\n            </table>\\n\\n            <table style=\\"width: 100%; border-collapse: collapse; margin-top: 40px;\\">\\n                <tr>\\n                    <td style=\\"width: 33%; text-align: center; padding-top: 30px; border-top: 1px solid #000;\\">\\n                        Customer Name &amp; Signature\\n                    </td>\\n                    <td style=\\"width: 34%; text-align: center; padding-top: 30px; border-top: 1px solid #000;\\">\\n                        Prepared By\\n                        <div style=\\"margin-top: 6px;\\" t-esc=\\"broker_name or ''\\"/>\\n                    </td>\\n                    <td style=\\"width: 33%; text-align: center; padding-top: 30px; border-top: 1px solid #000;\\">\\n                        Received By\\n                        <div style=\\"margin-top: 6px;\\"/>\\n                    </td>\\n                </tr>\\n            </table>\\n        </div>\\n        <t t-call=\\"bliss_property_management.tenancy_contract_terms_conditions\\"/>\\n    </t>"}	<t t-name="bliss_property_management.tenancy_contract_page">\n        <t t-set="company" t-value="doc.company_id"/>\n        <t t-set="company_partner" t-value="company.partner_id"/>\n        <t t-set="tenant" t-value="doc.partner_id"/>\n        <t t-set="unit" t-value="doc.unit_id"/>\n        <t t-set="installment_cheques" t-value="doc._get_rent_installment_cheques().sorted(key=lambda c: (c.cheque_date or False, c.id))"/>\n        <t t-set="office_commission" t-value="doc.commission_value and (doc.value * doc.commission_value / 100.0) or 0.0"/>\n        <t t-set="account_total" t-value="(doc.value or 0.0) + office_commission"/>\n        <t t-set="contract_status" t-value="'Renew' if doc.is_renew else ('New' if doc.state == 'signed' else doc.state)"/>\n        <t t-set="contract_type" t-value="'Renew' if doc.is_renew else 'New'"/>\n        <t t-set="report_date" t-value="doc.date or doc.date_start"/>\n        <t t-set="tenant_phone" t-value="tenant.phone"/>\n        <t t-set="broker_name" t-value="doc.user_id.name if doc.user_id else False"/>\n\n        <div class="page tenancy-contract-page" style="font-family: Arial, sans-serif; font-size: 11px; color: #000;">\n            <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px;">\n                <tr>\n                    <td style="width: 22%; vertical-align: top;"/>\n                    <td style="width: 56%; vertical-align: top; text-align: center; padding: 0 8px;">\n                        <div style="font-size: 17px; font-weight: bold; line-height: 1.35; margin-bottom: 4px;" t-esc="company.name or ''"/>\n                        <div style="font-size: 12px; line-height: 1.4;" t-if="company_partner.street" t-esc="company_partner.street"/>\n                        <div style="font-size: 12px; line-height: 1.4;">\n                            <t t-if="company_partner.city" t-esc="company_partner.city"/>\n                            <t t-if="company_partner.country_id">, <t t-esc="company_partner.country_id.name"/></t>\n                        </div>\n                        <div style="font-size: 12px; line-height: 1.4; margin-top: 2px;">\n                            <t t-if="company.phone">Tel: <t t-esc="company.phone"/></t>\n                            <t t-if="company.phone"> , </t>\n                            Fax: <t t-esc="company.company_registry or ''"/>\n                        </div>\n                    </td>\n                    <td style="width: 22%; vertical-align: top; text-align: right; font-size: 13px; line-height: 1.6; padding-top: 2px;">\n                        <div style="font-size: 13px; margin-bottom: 3px;">\n                            <span style="font-weight: bold;">Status :</span>\n                            <t t-esc="contract_status"/>\n                        </div>\n                        <div style="font-size: 13px; margin-bottom: 3px;">\n                            <span style="font-weight: bold;">Doc No :</span>\n                            <t t-esc="doc.code or 'code'"/>\n                        </div>\n                        <div style="font-size: 13px;">\n                            <span style="font-weight: bold;">Date :</span>\n                            <t t-if="report_date" t-esc="report_date" t-options="{'widget': 'date'}"/>\n                            <t t-else="">date</t>\n                        </div>\n                    </td>\n                </tr>\n            </table>\n\n            <div style="text-align: center; font-size: 18px; font-weight: bold; text-decoration: underline; margin: 12px 0 14px 0;">\n                TENANCY CONTRACT\n            </div>\n\n            <table style="width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 10px;">\n                <tr>\n                    <td colspan="6" style="border: 1px solid #000; padding: 4px 6px;">\n                        Tower Name :\n                        <t t-esc="doc.building_id.building_name if doc.building_id else ''"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Unit No :\n                        <t t-esc="unit.unit_no if unit and unit.unit_no else ''"/>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Unit Type :\n                        <t t-esc="unit.unit_type_id.name if unit and unit.unit_type_id else ''"/>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Floor :\n                        <t t-esc="unit.floor_no if unit and unit.floor_no else ''"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="6" style="border: 1px solid #000; padding: 4px 6px;">\n                        Tanent Name :\n                        <t t-esc="tenant.name if tenant else ''"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="6" style="border: 1px solid #000; padding: 4px 6px;">\n                        Chq. Payee Name :\n                        <t t-esc="tenant.name if tenant else ''"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="3" style="border: 1px solid #000; padding: 4px 6px;">\n                        Phone No :\n                        <t t-esc="tenant_phone if tenant_phone else ''"/>\n                    </td>\n                    <td colspan="3" rowspan="2" style="border: 1px solid #000; padding: 4px 6px; text-align: center; vertical-align: middle;">\n                        <div>Length of Tenancy</div>\n                        <div style="margin-top: 8px;">\n                            <t t-if="doc.no_of_days" t-esc="str(doc.no_of_days) + ' days'"/>\n                            <t t-else="">length_of_tenancy</t>\n                        </div>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="3" style="border: 1px solid #000; padding: 4px 6px;">\n                        EID :\n                        <t t-esc="tenant.emirateId_number if tenant and tenant.emirateId_number else ''"/>\n                        <span style="margin-left: 20px;">Nationality :\n                            <t t-esc="tenant.nationality.name if tenant and tenant.nationality else ''"/>\n                        </span>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Contract Type <t t-esc="contract_type"/>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Contract Start Date\n                        <t t-if="doc.date_start" t-esc="doc.date_start" t-options="{'widget': 'date'}"/>\n                        <t t-else="">date_start</t>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        End Date\n                        <t t-if="doc.date_stop" t-esc="doc.date_stop" t-options="{'widget': 'date'}"/>\n                        <t t-else="">date_stop</t>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Original Amount :\n                        <t t-esc="doc.format_report_currency(doc.value)"/>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Discount :\n                        <t t-esc="doc.discount or 0.0"/>\n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Net Amount :\n                        <t t-esc="doc.format_report_currency(doc.total_value)"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="3" style="border: 1px solid #000; padding: 4px 6px;">\n                        Previous Rent : \n                    </td>\n                    <td colspan="3" style="border: 1px solid #000; padding: 4px 6px;">\n                        Base Rent :\n                        <t t-esc="doc.format_report_currency(doc.value)"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Living Purpose: \n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Adv. Source: \n                    </td>\n                    <td colspan="2" style="border: 1px solid #000; padding: 4px 6px;">\n                        Broker:\n                        <t t-esc="broker_name if broker_name else ''"/>\n                    </td>\n                </tr>\n                <tr>\n                    <td colspan="6" style="border: 1px solid #000; padding: 4px 6px;">\n                        Notes:\n                        <t t-esc="doc.notes if doc.notes else ''"/>\n                    </td>\n                </tr>\n            </table>\n\n            <div style="font-weight: bold; margin: 6px 0 4px 0;">Account Details</div>\n            <table style="width: 100%; border-collapse: collapse; border: 1px solid #000; margin-bottom: 10px;">\n                <thead>\n                    <tr style="background-color: #f2f2f2;">\n                        <th style="border: 1px solid #000; padding: 4px; width: 8%;">S No</th>\n                        <th style="border: 1px solid #000; padding: 4px; width: 62%;">Particulars</th>\n                        <th style="border: 1px solid #000; padding: 4px; width: 30%; text-align: right;">Amount</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: center;">1</td>\n                        <td style="border: 1px solid #000; padding: 4px;">Rent</td>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: right;">\n                            <t t-esc="doc.format_report_currency(doc.value)"/>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: center;">2</td>\n                        <td style="border: 1px solid #000; padding: 4px;">Ejari Fees</td>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: right;">\n                        \n                            <t t-esc="doc.format_report_currency(doc.ejari_fees)"/>\n                        \n                        \n                        </td>\n                    </tr>\n                    <tr>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: center;">3</td>\n                        <td style="border: 1px solid #000; padding: 4px;">Office Commission</td>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: right;">\n                                <t t-if="doc.commission_value" t-esc="doc.format_report_currency(office_commission)"/>\n                            <t t-else=""/>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td colspan="2" style="border: 1px solid #000; padding: 4px; font-weight: bold;">TOTAL</td>\n                        <td style="border: 1px solid #000; padding: 4px; text-align: right; font-weight: bold;">\n                            <t t-esc="doc.format_report_currency(account_total)"/>\n       