                        </div>\n                            </div>\n                        </div>\n                        <div class="col-xs-12 col-md-6 o_setting_box">\n                            <div class="o_setting_left_pane"/>\n                            <div class="o_setting_right_pane">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="cheque_deferred_credit_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="cheque_deferred_credit_account_id"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <h2>Contract Termination Settlement</h2>\n                    <div class="row mt16 o_settings_container">\n                        <div class="col-xs-12 col-md-6 o_setting_box">\n                            <div class="o_setting_left_pane"/>\n                            <div class="o_setting_right_pane">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="termination_security_deposit_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_security_deposit_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="termination_penalty_income_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_penalty_income_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="termination_deferred_revenue_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_deferred_revenue_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="termination_revenue_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_revenue_account_id"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-xs-12 col-md-6 o_setting_box">\n                            <div class="o_setting_left_pane"/>\n                            <div class="o_setting_right_pane">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="termination_vat_output_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_vat_output_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="termination_payable_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_payable_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="termination_receivable_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="termination_receivable_account_id"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <h2>Maintenance Expense (Separate Billing)</h2>\n                    <div class="row mt16 o_settings_container">\n                        <div class="col-xs-12 col-md-6 o_setting_box">\n                            <div class="o_setting_left_pane"/>\n                            <div class="o_setting_right_pane">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="maintenance_expense_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="maintenance_expense_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="maintenance_management_fee_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="maintenance_management_fee_account_id"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        <div class="col-xs-12 col-md-6 o_setting_box">\n                            <div class="o_setting_left_pane"/>\n                            <div class="o_setting_right_pane">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="maintenance_clearing_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="maintenance_clearing_account_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="separate_maintenance_debit_account_id" class="col-md-4 o_light_label"/>\n                                        <field name="separate_maintenance_debit_account_id"/>\n                                    </div>\n                        