1388	16	\N	1	1	renewal_page1	\N	bliss_property_management.renewal_page1	qweb	bliss_property_management/report/renewal_notification_template.xml	primary	{"en_US": "<t t-name=\\"bliss_property_management.renewal_page1\\">\\n            <div class=\\"page\\" id=\\"page1\\">\\n                <div class=\\"container\\">\\n                    <div class=\\"row mx-5 my-0\\">\\n                        <div class=\\"col-12\\">\\n                            <table class=\\"table table-bordered border-dark\\">\\n                                <tbody>\\n                                    <tr>\\n                                        <td class=\\"align-top col-6\\">\\n                                            <p>Date:\\n                                                <span t-esc=\\"doc.date\\"/>\\n                                            </p>\\n                                            <p>Ref.No.: ALMULLA0001</p>\\n                                            <p>Tenant Name:\\n                                                <span t-esc=\\"doc.partner_id.name\\"/>\\n                                            </p>\\n                                            <p>Serial No: 01</p>\\n                                            <p>Area Name: Al Buteen, Dubai</p>\\n                                            <p>Tenant Address:\\n                                                <span t-esc=\\"doc.partner_id.street\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.street2\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.city\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.state_id.name\\"/>,\\n                                            </p>\\n                                            <p>Tenancy Contract Dated: <span t-esc=\\"doc.start_date_from\\"/></p>\\n                                        </td>\\n                                        <td class=\\"align-top col-6\\" dir=\\"rtl\\">\\n                                            <p>التاريخ : <span t-esc=\\"doc.date\\"/></p>\\n                                            <p>الرقم المرجعي: ALMULLA0001</p>\\n                                            <p> اسم المستأجر : <span t-esc=\\"doc.partner_id.name\\"/> </p>\\n                                            <p>رقم المسلسل: 01</p>\\n                                            <p>اسم المنطقة: آل بوثين، دبي</p>\\n                                            <p>عنوان المستأجر:  <span t-esc=\\"doc.partner_id.street\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.street2\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.city\\"/>,\\n                                                <span t-esc=\\"doc.partner_id.state_id.name\\"/></p>\\n                                            <p> تاريخ عقد الايجار: <span t-esc=\\"doc.start_date_from\\"/> </p>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td class=\\"col-6\\">\\n                                            <p>Delivered by:</p>\\n                                        </td>\\n                                        <td class=\\"col-6\\" dir=\\"rtl\\">\\n                                            <p>التسليم من قبل:</p>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td class=\\"col-6\\">\\n                                            <p>Dear Tenant:</p>\\n                                        </td>\\n                                        <td class=\\"col-6\\" dir=\\"rtl\\">\\n                                            <p>السلام عليكم ورحمة اللله وبركاته:</p>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td class=\\"col-6 text-center\\">\\n                                            <u>\\n                                                <h3>Renewal Notice</h3>\\n                                            </u>\\n                                        </td>\\n                                        <td class=\\"col-6 text-center\\">\\n                                            <u>\\n                                                <h3>خطاب تجديد</h3>\\n                                            </u>\\n                                        </td>\\n                                    </tr>\\n                                    <tr>\\n                                        <td class=\\"col-6\\">\\n                                            <p>We refer to your Tenancy Contract, which is due to expire on\\n                                                (\\"__/__/__\\").\\n                                            </p>\\n                                            <p>We hereby give you notice that if the Tenancy Contract is renewed, the\\n                                                form of the renewed tenancy contract will follow the template enclosed\\n                                                with this notice. Without limitation, the amendments to the current\\n                                                Tenancy Contract include:\\n                                            </p>\\n                                            <p>Annual Rent: According to Emiri Decree No. (2) of 2017, issuing the law,\\n                                                real estate rent in the Emirate of Ajman, the rent will become AED\\n                                                78,000.\\n                                            </p>\\n                                            <p>VAT Applicable for commercial use premises</p>\\n                                        </td>\\n                                        <td class=\\"col-6\\" dir=\\"rtl\\">\\n                                            <p>بالإشارة إلى عقد الإيجار الخاص بك، الذي سينتهي في تاريخ (\\"__/__/__\\").</p>\\n                                            <p>نرسل لكم هذا الإخطار، أنه في حال تم تجديد عقد الإيجار، فإنه سيتم إلحاق\\n                                                صيغة عقد الإيجار المجدد مع هذا الإشعار.\\n                                                على سبيل المثال لا الحصر، التعديلات على عقد الإيجار الحالي تتضمن ما يلي:\\n                                            </p>\\n                                            <p>مبلغ الإيجار السنوي: وفقًا للمرسوم الأميري رقم (2) لسنة 2017، بإصدار\\n                                                قانون\\n                                                إيجار العقارات في إمارة عجمان، سيصبح الإيجار 78,000 درهم.\\n                                            </p>\\n                                            <p>تطبق ضريبة القيمة المضافة على العقارات التجارية</p>\\n                                        </td>\\n                                    </tr>\\n\\n                                    <tr>\\n                                        <td class=\\"col-6\\">\\n                                            <p>If you wish to renew your Tenancy Contract, please visit the relevant\\n                                                office as detailed as per following address:\\n                                            </p>\\n                                            <p>Ajman, Liwara 01, Day to Day building</p>\\n                                            <p>Office 712 between 10:00 am to\\n                                                08:00 pm from Sunday to Thursday (excluding public holidays) bringing\\n                                                with you the following:\\n                                            </p>\\n                                            <ul>\\n                                                <li>Copy of valid passport and residence visa of the tenant (if tenant\\n                                                    is an individual).\\n                                                </li>\\n                                                <li>Copy of valid Emirates ID.</li>\\n                                                <li>Copy of trade license or certificate of incorporation (if tenant is\\n                                                    a company).\\n                                                </li>\\n                                                <li>Original notarized Power of Attorney in favor of the person who\\n                                                    intends to sign the renewed Tenancy Contract on behalf of the Tenant\\n                                                    and copy of valid passport, residence visa and Emirates ID of the\\n                                                    person who intends to sign the renewed\\n                                                    Tenancy Contract on behalf of the tenant.\\n                                                </li>\\n                                                <li>\\n                                                    Payments for renewal rent and renewal charges.\\n                                                </li>\\n                                            </ul>\\n                                        </td>\\n                                        <td class=\\"col-6\\" dir=\\"rtl\\">\\n                                            <p>إذا رغبتم في تجديد عقد الإيجار، يرجى زيارة المكتب\\n                                                في العنوان التالي:\\n                                            </p>\\n                                            <p>عجمان، ليوارا 01، مبنى دي تو دي، مكتب 712 بين 10:00 صباحاً حتى\\n                                                08:00 مساءً من الأحد إلى الخميس (باستثناء ايام العطل الرسمية) مع إحضار\\n                                                ما\\n                                                يلي:\\n                                            </p>\\n                                            <p>\\n                                                <ul style=\\"margin-right: 25px;\\">\\n                                                    <li>صورة عن جواز السفر الساري المفعول وتأشيرة الاقامة السارية\\n                                                        المفعول للمستأجر (إذا كان المستأجر\\n                                                        فردًا).\\n                                                    </li>\\n                                                    <li>صورة عن بطاقة الهوية الإماراتية سارية المفعول.</li>\\n                                                    <li>نسخة عن الرخصة التجارية أو شهادة التأسيس (إذا كان المستأجر\\n                                                        شركة).\\n                                                    </li>\\n                                                    <li>أصل الوكالة القانونية الموثقة من الكاتب العدل لصالح الشخص الذي\\n                                                        سيقوم بالتوقيع على عقد الإيجار\\n                                                        المجدد بالنيابة عن المستاجر و صورة عن جواز السفر الساري المفعول\\n                                                        وتأشيرة الإقامة السارية\\n                                                        المفعول و صورة عن بطاقة الهوية الإمارتية سارية المفعول للشخص\\n                                                        الذي سيقوم بالتوقيع على\\n                                                        عقد الإيجار المجدد بالنيابة عن المستأجر.\\n                                                    </li>\\n                                                    <li>\\n                                                        دفعات الإيجار المجدد و رسوم التجديد.\\n                                                    </li>\\n                                                </ul>\\n                                            </p>\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </t>"}	<t t-name="bliss_property_management.renewal_page1">\n            <div class="page" id="page1">\n                <div class="container">\n                    <div class="row mx-5 my-0">\n                        <div class="col-12">\n                            <table class="table table-bordered border-dark">\n                                <tbody>\n                                    <tr>\n                                        <td class="align-top col-6">\n                                            <p>Date:\n                                                <span t-esc="doc.date"/>\n                                            </p>\n                                            <p>Ref.No.: ALMULLA0001</p>\n                                            <p>Tenant Name:\n                                                <span t-esc="doc.partner_id.name"/>\n                                            </p>\n                                            <p>Serial No: 01</p>\n                                            <p>Area Name: Al Buteen, Dubai</p>\n                                            <p>Tenant Address:\n                                                <span t-esc="doc.partner_id.street"/>,\n                                                <span t-esc="doc.partner_id.street2"/>,\n                                                <span t-esc="doc.partner_id.city"/>,\n                                                <span t-esc="doc.partner_id.state_id.name"/>,\n                                            </p>\n                                            <p>Tenancy Contract Dated: <span t-esc="doc.start_date_from"/></p>\n                                        </td>\n                                        <td class="align-top col-6" dir="rtl">\n                                            <p>التاريخ : <span t-esc="doc.date"/></p>\n                                            <p>الرقم المرجعي: ALMULLA0001</p>\n                                            <p> اسم المستأجر : <span t-esc="doc.partner_id.name"/> </p>\n                                            <p>رقم المسلسل: 01</p>\n                                            <p>اسم المنطقة: آل بوثين، دبي</p>\n                                            <p>عنوان المستأجر:  <span t-esc="doc.partner_id.street"/>,\n                                                <span t-esc="doc.partner_id.street2"/>,\n                                                <span t-esc="doc.partner_id.city"/>,\n                                                <span t-esc="doc.partner_id.state_id.name"/></p>\n                                            <p> تاريخ عقد الايجار: <span t-esc="doc.start_date_from"/> </p>\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td class="col-6">\n                                            <p>Delivered by:</p>\n                                        </td>\n                                        <td class="col-6" dir="rtl">\n                                            <p>التسليم من قبل:</p>\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td class="col-6">\n                                            <p>Dear Tenant:</p>\n                                        </td>\n                                        <td class="col-6" dir="rtl">\n                                            <p>السلام عليكم ورحمة اللله وبركاته:</p>\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td class="col-6 text-center">\n                                            <u>\n                                                <h3>Renewal Notice</h3>\n                                            </u>\n                                        </td>\n                                        <td class="col-6 text-center">\n                                            <u>\n                                                <h3>خطاب تجديد</h3>\n                                            </u>\n                                        </td>\n                                    </tr>\n                                    <tr>\n                                        <td class="col-6">\n                                            <p>We refer to your Tenancy Contract, which is due to expire on\n                                                ("__/__/__").\n                                            </p>\n                                            <p>We hereby give you notice that if the Tenancy Contract is renewed, the\n                                                form of the renewed tenancy contract will follow the template enclosed\n                                                with this notice. Without limitation, the amendments to the current\n                                                Tenancy Contract include:\n                                            </p>\n                                            <p>Annual Rent: According to Emiri Decree No. (2) of 2017, issuing the law,\n                                                real estate rent in the Emirate of Ajman, the rent will become AED\n                                                78,000.\n                                            </p>\n                                            <p>VAT Applicable for commercial use premises</p>\n                                        </td>\n                                        <td class="col-6" dir="rtl">\n                                            <p>بالإشارة إلى عقد الإيجار الخاص بك، الذي سينتهي في تاريخ ("__/__/__").</p>\n                                            <p>نرسل لكم هذا الإخطار، أنه في حال تم تجديد عقد الإيجار، فإنه سيتم إلحاق\n                                                صيغة عقد الإيجار المجدد مع هذا الإشعار.\n                                                على سبيل المثال لا الحصر، التعديلات على عقد الإيجار الحالي تتضمن ما يلي:\n                                            </p>\n                                            <p>مبلغ الإيجار السنوي: وفقًا للمرسوم الأميري رقم (2) لسنة 2017، بإصدار\n                                                قانون\n                                                إيجار العقارات في إمارة عجمان، سيصبح الإيجار 78,000 درهم.\n                                            </p>\n                                            <p>تطبق ضريبة القيمة المضافة على العقارات التجارية</p>\n                                        </td>\n                                    </tr>\n\n                                    <tr>\n                                        <td class="col-6">\n                                            <p>If you wish to renew your Tenancy Contract, please visit the relevant\n                                                office as detailed as per following address:\n                                            </p>\n                                            <p>Ajman, Liwara 01, Day to Day building</p>\n                                            <p>Office 712 between 10:00 am to\n                                                08:00 pm from Sunday to Thursday (excluding public holidays) bringing\n                                                with you the following:\n                                            </p>\n                                            <ul>\n                                                <li>Copy of valid passport and residence visa of the tenant (if tenant\n                                                    is an individual).\n                                                </li>\n                                                <li>Copy of valid Emirates ID.</li>\n                                                <li>Copy of trade license or certificate of incorporation (if tenant is\n                                                    a company).\n                                                </li>\n                                                <li>Original notarized Power of Attorney in favor of the person who\n                                                    intends to sign the renewed Tenancy Contract on behalf of the Tenant\n                                                    and copy of valid passport, residence visa and Emirates ID of the\n                                                    person who intends to sign the renewed\n                                                    Tenancy Contract on behalf of the tenant.\n                                                </li>\n                                                <li>\n                                                    Payments for renewal rent and renewal charges.\n                                                </li>\n                                            </ul>\n                                        </td>\n                                        <td class="col-6" dir="rtl">\n                                            <p>إذا رغبتم في تجديد عقد الإيجار، يرجى زيارة المكتب\n                                                في العنوان التالي:\n                                            </p>\n                                            <p>عجمان، ليوارا 01، مبنى دي تو دي، مكتب 712 بين 10:00 صباحاً حتى\n                                                08:00 مساءً من الأحد إلى الخميس (باستثناء ايام العطل الرسمية) مع إحضار\n                                                ما\n                                                يلي:\n                                            </p>\n                                            <p>\n                                                <ul style="margin-right: 25px;">\n                                                    <li>صورة عن جواز السفر الساري المفعول وتأشيرة الاقامة السارية\n                                                        المفعول للمستأجر (إذا كان المستأجر\n                                                        فردًا).\n                                                    </li>\n                                                    <li>صورة عن بطاقة الهوية الإماراتية سارية المفعول.</li>\n                                                    <li>نسخة عن الرخصة التجارية أو شهادة التأسيس (إذا كان المستأجر\n                                                        شركة).\n                                                    </li>\n                                                    <li>أصل الوكالة القانونية الموثقة من الكاتب العدل لصالح الشخص الذي\n                                                        سيقوم بالتوقيع على عقد الإيجار\n                                                        المجدد بالنيابة عن المستاجر و صورة عن جواز السفر الساري المفعول\n                                                        وتأشيرة الإقامة السارية\n                                                        المفعول و صورة عن بطاقة الهوية الإمارتية سارية المفعول للشخص\n                                                        الذي سيقوم بالتوقيع على\n                                                        عقد الإيجار المجدد بالنيابة عن المستأجر.\n                                                    </li>\n                                                    <li>\n                                                        دفعات الإيجار المجدد و رسوم التجديد.\n                                                    </li>\n                                                </ul>\n                                            </p>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>	f	t	2026-05-21 05:58:30.798532	2026-11-25 07:18:02.706036	f
